-- Fichier généré par outils/convertir_articles.mjs (lib/journal/import-sql.ts) : ne pas modifier à la main.
--
-- Import des articles du journal d'avant le back office (contenu/journal/*.mdx),
-- publiés : en-tête → colonnes, corps Markdown → document de l'éditeur
-- (lib/journal/conversion.ts, la même conversion que les données de secours).
-- Publication : la date de l'article, à midi heure de Paris. Identifiants fixes
-- (UUID v5 du slug). Rejouable : un article déjà présent (id ou slug) est ignoré.
-- 37 articles, 107 photos dans les textes.

-- comment-bien-choisir-son-dj-les-criteres-a-connaitre
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'baddac3b-196a-5ccd-9f8f-e5c9cc7fe856', 'publie', '2026-01-27T12:00:00+01:00'::timestamptz, 'comment-bien-choisir-son-dj-les-criteres-a-connaitre',
  'Comment bien choisir son DJ : les critères à connaître',
  'Toutes les clés à connaître',
  'Choisir son DJ, ce n’est pas simplement sélectionner quelqu’un qui passera de la musique le jour J.',
  'Musique & ambiance', '2026-01-27'::date,
  '/journal/comment-bien-choisir-son-dj-les-criteres-a-connaitre/couverture.jpg',
  'DJ aux platines sous les projecteurs',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Choisir son "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", ce n’est pas simplement sélectionner quelqu’un qui passera de la musique le jour J. Chez Spice Events, nous sommes convaincus que le "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" est l’un des piliers de votre événement, à la fois chef d’orchestre de l’ambiance, repère pour le timing et garant du confort sonore de vos invités."}]},{"type":"paragraph","content":[{"type":"text","text":"Voici les critères essentiels à prendre en compte pour faire un vrai choix de qualité."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un DJ qui comprend votre événement, pas seulement votre playlist"}]},{"type":"paragraph","content":[{"type":"text","text":"Un bon "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" commence par écouter. Vos envies, votre histoire, le type d’événement, le public attendu, le lieu… tout compte. Chez Spice Events, chaque projet démarre par un échange approfondi afin de comprendre l’atmosphère recherchée et les temps forts à mettre en valeur. Le rôle du "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" est de traduire votre univers en ambiance musicale, pas d’imposer un style ou une sélection toute faite."}]},{"type":"image","attrs":{"src":"/journal/comment-bien-choisir-son-dj-les-criteres-a-connaitre/1.jpg","width":1200,"height":799,"alt":"DJ aux platines sous les projecteurs"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’accompagnement en amont : la clé d’un événement fluide"}]},{"type":"paragraph","content":[{"type":"text","text":"Un "},{"type":"text","text":"DJ professionnel","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" travaille bien avant le jour J. Il vous "},{"type":"text","text":"accompagne","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" dans la construction du déroulé, vous aide à anticiper les moments importants et vous conseille sur les choix techniques et artistiques. Chez Spice Events, "},{"type":"text","text":"cet accompagnement fait partie intégrante de la prestation","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" : conseils sur le rythme de la journée, enchaînement des temps forts, gestion des transitions, cohérence entre cérémonie, cocktail et soirée. Tout est pensé pour que l’événement se déroule naturellement, sans ruptures ni temps morts."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le DJ, garant du timing et de l’équilibre"}]},{"type":"paragraph","content":[{"type":"text","text":"Au-delà de la musique, le "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" joue un rôle central dans le timing. Il sait quand lancer un moment fort, quand ralentir, quand relancer l’énergie ou au contraire laisser place à l’émotion. Un bon "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ne cherche pas à être omniprésent : il s’adapte, observe et ajuste en permanence pour respecter le rythme de vos invités et l’esprit de votre événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le matériel : un critère souvent invisible, mais essentiel"}]},{"type":"paragraph","content":[{"type":"text","text":"La qualité du matériel change radicalement l’expérience. Une "},{"type":"text","text":"sonorisation","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" bien dimensionnée assure une diffusion claire, homogène et confortable, aussi bien pour les discours que pour la musique. Un "},{"type":"text","text":"éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" maîtrisé sublime les espaces sans éblouir ni fatiguer. Chez Spice Events, nous attachons une importance particulière au choix du matériel, issu de références professionnelles, et toujours adapté au lieu, à la configuration et au nombre d’invités. Le matériel ne doit jamais se faire remarquer… sauf par sa qualité."}]},{"type":"image","attrs":{"src":"/journal/comment-bien-choisir-son-dj-les-criteres-a-connaitre/2.jpg","width":1200,"height":799,"alt":"Mains d''un DJ sur une table de mixage éclairée en bleu"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une vision globale de l’événement"}]},{"type":"paragraph","content":[{"type":"text","text":"Choisir Spice Events, c’est choisir une approche complète : "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", "},{"type":"text","text":"accompagnement","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":", "},{"type":"text","text":"sonorisation, éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" et "},{"type":"text","text":"animations tendances","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" pensés comme un tout. Chaque élément est cohérent avec les autres pour créer une ambiance fluide, élégante et immersive. Nous ne proposons pas une simple "},{"type":"text","text":"prestation DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", mais une vision d’ensemble au service de votre événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le bon DJ est celui qui vous ressemble"}]},{"type":"paragraph","content":[{"type":"text","text":"Le critère final reste la confiance. Un bon "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" est celui avec qui vous vous sentez compris, rassuré et "},{"type":"text","text":"accompagné","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":". Celui qui sait vous guider sans jamais vous imposer ses choix. Chez Spice Events, notre objectif est simple : créer une ambiance juste, sincère et mémorable, en respectant votre identité et l’émotion de chaque instant. Parce qu’un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ne se contente pas de passer de la musique : il donne du sens à vos moments."}]}]}'::jsonb
) on conflict do nothing;

-- comment-choisir-l-ambiance-musicale-de-votre-mariage
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'ac336f7a-2094-5f18-a73a-7bacb1642ba5', 'publie', '2021-10-05T12:00:00+02:00'::timestamptz, 'comment-choisir-l-ambiance-musicale-de-votre-mariage',
  'Comment choisir l''ambiance musicale de votre mariage ?',
  'Vous hésitez encore en ce qui concerne la musique de votre mariage? DJ, groupe, orchestre… Spice vous aide dans vos choix.',
  'Avant toute chose votre mariage doit être à votre image alors faites vous confiance. Tous vos invités n’auront d’yeux que pour vous, soyez à l’aise et brillez !',
  'Musique & ambiance', '2021-10-05'::date,
  '/journal/comment-choisir-l-ambiance-musicale-de-votre-mariage/couverture.jpg',
  'Invités dansant en plein air sous des guirlandes lumineuses',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Avant toute chose votre mariage doit être à votre image alors faites vous confiance. Tous vos invités n’auront d’yeux que pour vous, soyez à l’aise et brillez !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"De la musique pour chaque instant"}]},{"type":"paragraph","content":[{"type":"text","text":"En plus d’être un jour exceptionnel pour vous et votre conjoint(e), votre mariage est une journée de retrouvailles ou de rencontres pour vos proches, l’ambiance se doit d’être au rendez-vous."}]},{"type":"paragraph","content":[{"type":"text","text":"Il est possible de varier les animations musicales pour les adapter à chaque moment de cette journée."}]},{"type":"paragraph","content":[{"type":"text","text":"Lors de l’échange des vœux, une ambiance calme et romantique est recommandée pour une émotion garantie. Dans cette optique, choisissez un pianiste ou un orchestre. Vous verrez les yeux brillants de vos invités, à moins que les vôtres ne soient déjà trop mouillés !"}]},{"type":"paragraph","content":[{"type":"text","text":"Pour l’entrée des mariés, si vous souhaitez rester dans une ambiance douce et pleine d''émotions, continuez avec un pianiste. Mais si vous désirez une arrivée plus festive, choisissez une fanfare. Elle apportera rythme et joie à cet accueil."}]},{"type":"paragraph","content":[{"type":"text","text":"A l’heure du cocktail, vous avez le choix. Poursuivez avec le pianiste si vous recherchez une atmosphère douce mais si vous préférez plus de pep’s pour commencer à rythmer votre soirée, alors faites appel à une troupe de samba. Une animation sensationnelle qui fera voyager tous vos invités en Amérique du Sud."}]},{"type":"paragraph","content":[{"type":"text","text":"En ce qui concerne le repas, orientez-vous vers des musiques plus calmes mais rythmées. Ainsi vos invités pourront accompagner leur repas d’une petite musique agréable et enjouée."}]},{"type":"paragraph","content":[{"type":"text","text":"Quant à la soirée dansante, rien de mieux qu’un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". Faites confiance à nos professionnels qui sauront s''adapter et captiver vos convives jusqu’au bout de la nuit."}]},{"type":"image","attrs":{"src":"/journal/comment-choisir-l-ambiance-musicale-de-votre-mariage/1.jpg","width":800,"height":533,"alt":"Mains sur un contrôleur DJ dans une lumière violette"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pour toutes les générations"}]},{"type":"paragraph","content":[{"type":"text","text":"Le mariage c’est aussi un événement multigénérationnel alors il faut faire plaisir à tout le monde."}]},{"type":"paragraph","content":[{"type":"text","text":"La musique est l''élément clé qui rendra cette journée encore plus inoubliable. Et pour qu’elle marque les esprits, il faut qu’elle plaise autant à Mamie qu’à votre petite nièce. Tout le monde doit s’amuser."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour réussir cette mission, Spice vous propose son "},{"type":"text","text":"bar à vinyle","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":". Choisissez ou laissez vos invités se porter sur ce large choix de disques, vous tomberez forcément sur LA musique, celle remplie de souvenirs et de nostalgie. De plus, ce bar est parfait pour une ambiance rétro !"}]},{"type":"paragraph","content":[{"type":"text","text":"Encore une fois, vous pouvez compter sur nos "},{"type":"text","text":"DJ d''exception","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", ils sauront s’adapter à tous les types de cérémonies. Ils offriront une animation adaptée à chaque tranche d’âge !"}]},{"type":"paragraph","content":[{"type":"text","text":"Avec tout cela, vos convives seront heureux de voir que vous avez pensé à eux."}]},{"type":"image","attrs":{"src":"/journal/comment-choisir-l-ambiance-musicale-de-votre-mariage/2.jpg","width":800,"height":533,"alt":"Disques vinyles sur une platine"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Et pour tous les styles"}]},{"type":"paragraph","content":[{"type":"text","text":"Outre l’âge, les styles aussi diffèrent. Une fois de plus, il va falloir faire varier les plaisirs."}]},{"type":"paragraph","content":[{"type":"text","text":"Le "},{"type":"text","text":"groupe de jazz","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" est une bonne idée si l’ambiance recherchée se veut romantique et chaleureuse."}]},{"type":"paragraph","content":[{"type":"text","text":"Vous pouvez également vous laisser tenter par la venue d’un saxophoniste. Cet instrument classe pourra vous accompagner lors de l’entrée des mariés, du cocktail ou encore sur la piste de danse."}]},{"type":"paragraph","content":[{"type":"text","text":"Sinon pour les personnes fans des années 70, il existe la disco party. Un retour dans le temps exceptionnel rythmé de funk et de pop."}]},{"type":"image","attrs":{"src":"/journal/comment-choisir-l-ambiance-musicale-de-votre-mariage/3.jpg","width":800,"height":534,"alt":"Boules à facettes suspendues"}},{"type":"paragraph","content":[{"type":"text","text":"Vous l''aurez compris, que votre cérémonie se déroule en plein air, à la mairie ou à l’église, votre ambiance doit être choisie minutieusement."}]},{"type":"paragraph","content":[{"type":"text","text":"Si avec toutes ces informations, vous avez encore des doutes ou ne savez pas comment vous y prendre, Spice est là pour vous accompagner dans vos interrogations."}]},{"type":"paragraph","content":[{"type":"text","text":"N’hésitez pas à venir vers nous pour toutes questions, nous nous ferons un plaisir de vous répondre.","marks":[{"type":"link","attrs":{"href":"/contact"}}]}]}]}'::jsonb
) on conflict do nothing;

-- comment-faire-durer-la-magie-du-jour-j
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '04e156aa-58a4-5687-be90-c543df42e4c3', 'publie', '2022-04-05T12:00:00+02:00'::timestamptz, 'comment-faire-durer-la-magie-du-jour-j',
  'Comment faire durer la magie du Jour-J ?',
  'Nos astuces spicy',
  'Votre mariage est l’un, voire LE plus beau jour de votre vie. Mais pourquoi la magie ne devrait-elle durer qu’une journée ?',
  'Conseils mariage', '2022-04-05'::date,
  '/journal/comment-faire-durer-la-magie-du-jour-j/couverture.jpg',
  'Livre d''or en lin orné de dentelle et de fleurs séchées',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Votre mariage est l’un, voire LE plus beau jour de votre vie. Mais pourquoi la magie ne devrait-elle durer qu’une journée ? Voici de petites astuces à réaliser le Jour-J pour que la magie perdure."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Souriez, c’est dans le Booth !"}]},{"type":"paragraph","content":[{"type":"text","text":"Si vous ne souhaitez pas faire appel à un photographe professionnel pour votre mariage, pas de soucis, des alternatives existent."}]},{"type":"paragraph","content":[{"type":"text","text":"Avec Spice Events, il est possible de louer un "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":". Très tendance, c’est un appareil photo géant autonome. Grâce à lui, plus besoin de photographe, votre présence suffit. Placez-vous devant l''objectif, choisissez le format de votre photo, souriez, c’est imprimé !"}]},{"type":"paragraph","content":[{"type":"text","text":"Et comme Spice Events pense aussi à la planète, l’impression n’est pas automatique, ni obligatoire. Vous pouvez en un clic vous envoyer la photo par e-mail et la conserver sur votre téléphone. Le "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":" est accessible à tous, à tout moment de la journée. Un bon moyen de divertir vos invités et de garder de jolies photos d’eux mais aussi de vous !"}]},{"type":"paragraph","content":[{"type":"text","text":"Une fois le mariage passé, vous pouvez décider d’en faire un bel album souvenir ou si vous souhaitez être plus original et faire un clin d''œil à vos proches, vous pouvez en faire des cartes de remerciements en choisissant soigneusement pour chacun, la photo idéale prise avec notre "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":" lors de cette journée."}]},{"type":"paragraph","content":[{"type":"text","text":"Tout comme vous, vos amis et votre famille ont partagé un moment inoubliable et riche en émotion et auraient aimé que ça ne s’arrête pas aussi vite ! Ils seront alors très heureux de pouvoir se remémorer cet instant de la soirée, grâce à votre carte de remerciement personnalisée et unique."}]},{"type":"image","attrs":{"src":"/journal/comment-faire-durer-la-magie-du-jour-j/1.jpg","width":2400,"height":1600,"alt":"Vieilles photos rangées dans un album souvenir"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Garder de la décoration"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice Events, on vous propose plusieurs thématiques : blanc, noir, bois et végétal."}]},{"type":"paragraph","content":[{"type":"text","text":"Après le Jour-J il est possible de garder des éléments de décoration et de les placer chez vous ou de les mettre dans une boîte à souvenirs, accompagné de petites photos prises avec notre "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":" ! Vous pouvez également conserver précieusement votre bouquet de mariage, encore faut-il convaincre vos invités qu’il est plus symbolique de le garder plutôt que de se prêter au typique lancer de la mariée."}]},{"type":"paragraph","content":[{"type":"text","text":"Vos proches peuvent également repartir s’ils le souhaitent avec un souvenir, comme par exemple, leur nom de table de mariage."}]},{"type":"image","attrs":{"src":"/journal/comment-faire-durer-la-magie-du-jour-j/2.jpg","width":2400,"height":1602,"alt":"Bouquet de la mariée tenu par les mariés"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Vidéo souvenir"}]},{"type":"paragraph","content":[{"type":"text","text":"Plus original et moderne que les photos : les vidéos souvenirs. Elles sont de plus en plus utilisées pour garder le souvenir d’un événement. Un vidéaste peut assister à votre mariage et ensuite réaliser un film, vos proches peuvent monter une jolie vidéo de messages personnalisés, avant ou pendant le mariage..."}]},{"type":"paragraph","content":[{"type":"text","text":"Il existe aujourd’hui mille et une façons de se créer des souvenirs vidéo, et de pouvoir les regarder à n’importe quel moment de votre vie."}]},{"type":"paragraph","content":[{"type":"text","text":"Si vous ne savez pas vers qui vous tourner en ce qui concerne le matériel vidéo, Spice Events se fera un plaisir de vous "},{"type":"text","text":"conseiller","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":"."}]},{"type":"image","attrs":{"src":"/journal/comment-faire-durer-la-magie-du-jour-j/3.jpg","width":2400,"height":1600,"alt":"Caméra vidéo professionnelle"}},{"type":"paragraph","content":[{"type":"text","text":"Maintenant que vous êtes des experts en création de souvenirs, on est impatient de voir ce que vous avez choisi !"}]}]}'::jsonb
) on conflict do nothing;

-- comment-un-bon-eclairage-fait-paraitre-un-lieu-plus-haut-de-gamme
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'd7321f9f-bc31-5bf9-80c4-480aea9b147b', 'publie', '2026-03-27T12:00:00+01:00'::timestamptz, 'comment-un-bon-eclairage-fait-paraitre-un-lieu-plus-haut-de-gamme',
  'Comment un bon éclairage fait paraître un lieu plus haut de gamme',
  'L’éclairage, premier levier de perception',
  'Lorsqu’un invité découvre un lieu de réception, son premier ressenti est visuel.',
  'Technique', '2026-03-27'::date,
  '/journal/comment-un-bon-eclairage-fait-paraitre-un-lieu-plus-haut-de-gamme/couverture.jpg',
  'Salle d''exposition éclairée en bleu, voitures et mange-debout lumineux',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lorsqu’un invité découvre un lieu de réception, son premier ressenti est visuel. Avant même la musique ou l’ambiance générale, c’est la lumière qui structure l’espace et influence immédiatement la perception du lieu. Un "},{"type":"text","text":"éclairage bien pensé","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" peut transformer une salle classique en un environnement élégant et immersif. À l’inverse, une lumière mal adaptée peut rapidement donner une impression froide ou impersonnelle, même dans un lieu de qualité."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sublimer l’architecture et les volumes"}]},{"type":"paragraph","content":[{"type":"text","text":"Un "},{"type":"text","text":"bon éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" ne se contente pas d’illuminer un espace, il le met en valeur. En travaillant les hauteurs, les murs, les colonnes ou les éléments architecturaux, il est possible de donner de la profondeur et du relief à un lieu. Certaines configurations permettent même de “redessiner” visuellement l’espace, en accentuant les volumes ou en structurant les différentes zones. Cette mise en valeur donne immédiatement une impression plus haut de gamme et plus travaillée."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Créer une ambiance cohérente et maîtrisée"}]},{"type":"paragraph","content":[{"type":"text","text":"L’un des marqueurs d’un événement premium est la cohérence. L’"},{"type":"text","text":"éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" joue ici un rôle central. Température de couleur, intensité lumineuse et choix des teintes doivent être alignés avec l’univers du "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou de l’"},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":". Une lumière trop forte ou mal équilibrée peut casser l’ambiance, tandis qu’un éclairage maîtrisé crée une atmosphère élégante, chaleureuse et immersive. Cette cohérence visuelle renforce la perception de qualité globale."}]},{"type":"image","attrs":{"src":"/journal/comment-un-bon-eclairage-fait-paraitre-un-lieu-plus-haut-de-gamme/1.jpg","width":1800,"height":1350,"alt":"Salle d''exposition éclairée en bleu, voitures et mange-debout lumineux"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Accompagner les temps forts de la soirée"}]},{"type":"paragraph","content":[{"type":"text","text":"Un lieu haut de gamme ne repose pas uniquement sur son apparence statique, mais sur sa capacité à évoluer au fil de la soirée. L’"},{"type":"text","text":"éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" permet d’accompagner cette progression. Une ambiance douce et chaleureuse pour le dîner, puis une montée en intensité pour la soirée dansante, créent une véritable dynamique. Cette évolution subtile donne du rythme à l’événement et renforce l’impact des moments clés."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Mettre en valeur sans surcharger"}]},{"type":"paragraph","content":[{"type":"text","text":"L’élégance repose souvent sur la justesse. Un "},{"type":"text","text":"éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" trop présent ou trop complexe peut rapidement nuire à la perception haut de gamme. L’objectif n’est pas de multiplier les effets, mais de créer une ambiance lisible et harmonieuse. Des choix simples, bien exécutés, auront toujours plus d’impact qu’une accumulation d’effets lumineux. La maîtrise de l’intensité et du placement est essentielle pour conserver une esthétique raffinée."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une signature professionnelle"}]},{"type":"paragraph","content":[{"type":"text","text":"Même si les invités ne l’analysent pas consciemment, "},{"type":"text","text":"un éclairage de qualité se ressent immédiatement","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":". Il participe à cette impression que “tout est bien fait”. Cette perception est un marqueur fort de professionnalisme et de niveau de prestation. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"chaque installation lumière est pensée pour s’intégrer parfaitement au lieu","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" et renforcer son potentiel, sans jamais le dénaturer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Transformer un lieu sans le changer"}]},{"type":"image","attrs":{"src":"/journal/comment-un-bon-eclairage-fait-paraitre-un-lieu-plus-haut-de-gamme/2.jpg","width":813,"height":542,"alt":"Salle de réception historique illuminée pendant une soirée dansante"}},{"type":"paragraph","content":[{"type":"text","text":"L’un des avantages majeurs de l’"},{"type":"text","text":"éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" est sa capacité à transformer un espace sans modification structurelle. Un lieu simple peut devenir élégant, chaleureux ou spectaculaire grâce à une mise en lumière adaptée. Cette transformation est souvent ce qui marque les invités et donne cette impression de standing supérieur."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’approche Spice Events"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", l’"},{"type":"text","text":"éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" est envisagé comme un véritable outil de mise en scène. Chaque projet fait l’objet d’une réflexion globale afin de créer une ambiance cohérente, adaptée au lieu et aux attentes des clients. L’objectif est simple : sublimer l’existant et offrir une "},{"type":"text","text":"expérience visuelle","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" à la hauteur de l’événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"En conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Un "},{"type":"text","text":"bon éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" ne se limite pas à éclairer un lieu, il en révèle tout le potentiel. Il structure l’espace, renforce l’ambiance et élève immédiatement la perception globale de l’événement. Dans un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" comme dans tout "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", c’est souvent ce niveau de détail qui fait la différence entre une belle soirée et une expérience réellement haut de gamme."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour en savoir plus sur notre approche et nos prestations, rendez-vous sur "},{"type":"text","text":"www.spiceevents.fr","marks":[{"type":"link","attrs":{"href":"/"}}]},{"type":"text","text":"."}]}]}'::jsonb
) on conflict do nothing;

-- comment-un-dj-lit-il-une-piste-de-danse
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '4f817844-7f6d-5ff7-a0b8-e269c30c74b6', 'publie', '2026-02-03T12:00:00+01:00'::timestamptz, 'comment-un-dj-lit-il-une-piste-de-danse',
  'Comment un DJ lit-il une piste de danse ?',
  'L''art de comprendre l''énergie d''un public en temps réel',
  'Lire une piste de danse est l’une des compétences les plus importantes – et les plus invisibles – du métier de DJ.',
  'Musique & ambiance', '2026-02-03'::date,
  '/journal/comment-un-dj-lit-il-une-piste-de-danse/couverture.jpg',
  'Piste de danse animée sous une lumière rose',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lire une piste de danse est l’une des compétences les plus importantes – et les plus invisibles – du métier de "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". Ce savoir-faire ne repose pas uniquement sur la musique, mais sur l’observation, l’écoute et la capacité à s’adapter en temps réel. Un bon "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ne se contente jamais d’enchaîner des titres : il interprète une salle, ressent une énergie et guide les invités tout au long de la soirée."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Comprendre l’environnement avant même de lancer la musique"}]},{"type":"paragraph","content":[{"type":"text","text":"La lecture de la piste commence bien avant le premier morceau. Le "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" observe le lieu, la disposition de la salle, la proximité entre la piste et les tables, la lumière, l’acoustique et la circulation des invités. Tous ces éléments influencent la façon dont les personnes vont se déplacer, se rassembler et oser aller danser. Il analyse également le profil des invités : générations présentes, styles vestimentaires, dynamique de groupe, ambiance générale. Ces informations permettent d’anticiper les styles musicaux qui créeront naturellement un premier lien avec la piste de danse."}]},{"type":"image","attrs":{"src":"/journal/comment-un-dj-lit-il-une-piste-de-danse/1.jpg","width":2048,"height":1363,"alt":"Piste de danse pleine devant la régie DJ"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Lire les signaux faibles de la piste"}]},{"type":"paragraph","content":[{"type":"text","text":"Lire une piste de danse, ce n’est pas seulement regarder qui danse. Ce sont les micro-signaux qui comptent : un pied qui tape, des têtes qui bougent, des regards tournés vers la régie, des refrains chantés depuis les tables. Ces réactions indiquent si la musique touche les invités, même lorsqu’ils ne sont pas encore sur la piste. Un "},{"type":"text","text":"DJ expérimenté","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" sait que l’engagement commence souvent avant le premier pas de danse."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Gérer les temps forts et les temps de respiration"}]},{"type":"paragraph","content":[{"type":"text","text":"Une piste de danse fonctionne par vagues. Il y a des moments d’explosion collective et des phases plus calmes. Un bon "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" sait respecter ces cycles. Forcer une montée trop rapide ou enchaîner uniquement des titres très énergiques peut fatiguer les invités et vider la piste. Lire la piste, c’est savoir quand ralentir légèrement le tempo, quand proposer un morceau plus chantant, ou quand relancer avec un titre fédérateur capable de rassembler toutes les générations."}]},{"type":"image","attrs":{"src":"/journal/comment-un-dj-lit-il-une-piste-de-danse/2.jpg","width":1200,"height":799,"alt":"Invités dansant sous des lasers verts devant la régie DJ"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Adapter la musique en temps réel"}]},{"type":"paragraph","content":[{"type":"text","text":"Contrairement à une playlist figée, la lecture de piste implique une adaptation permanente. Si un style fonctionne particulièrement bien, le "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" peut prolonger cette énergie. Si l’ambiance baisse, il doit être capable de changer de direction rapidement, sans créer de rupture brutale. Cela passe par le choix des morceaux, mais aussi par les transitions, le volume, la durée des titres et le moment précis où lancer un refrain clé."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Anticiper plutôt que corriger"}]},{"type":"paragraph","content":[{"type":"text","text":"Un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" qui lit correctement une piste n’attend pas que celle-ci se vide pour réagir. Il sent les signes avant-coureurs : des invités qui quittent la piste, une énergie qui retombe, une attention qui se disperse. Il anticipe alors la relance musicale idéale pour maintenir la dynamique et garder les invités engagés. Cette capacité d’anticipation est ce qui permet de conserver une piste de danse vivante et pleine sur la durée."}]},{"type":"image","attrs":{"src":"/journal/comment-un-dj-lit-il-une-piste-de-danse/3.jpg","width":1418,"height":945,"alt":"Invités bras levés sur une piste de danse éclairée en bleu"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une compétence humaine avant tout"}]},{"type":"paragraph","content":[{"type":"text","text":"Lire une piste de danse est avant tout une question de sensibilité humaine. Cela demande de l’expérience, de l’écoute et une vraie capacité à se connecter aux invités. Chaque soirée est différente, chaque public a sa propre énergie, et aucune recette ne fonctionne à l’identique deux fois."}]},{"type":"paragraph","content":[{"type":"text","text":"Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", cette lecture fine de la piste de danse fait partie intégrante de chaque "},{"type":"text","text":"prestation DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". C’est ce qui nous permet de créer des ambiances fluides, cohérentes et mémorables, où chaque invité trouve sa place et vit pleinement l’instant."}]},{"type":"paragraph","content":[{"type":"text","text":"Parce qu’une piste de danse ne se contrôle pas. Elle se comprend, se respecte et se guide."}]}]}'::jsonb
) on conflict do nothing;

-- de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'd695fad8-3394-559c-ae4d-1978197f8309', 'publie', '2026-02-11T12:00:00+01:00'::timestamptz, 'de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage',
  'De visiteurs à exposants : l’envers du décor d’un Salon du Mariage',
  'Quand préparation, exigence et passion deviennent la signature de chaque mariage',
  'Lors du dernier Salon du Mariage, l’équipe Spice Events était derrière le comptoir… mais aussi dans une multitude de rôles à la fois.',
  'Conseils mariage', '2026-02-11'::date,
  '/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/couverture.jpg',
  'Stand Spice Events au Salon du Mariage',
  '{"type":"doc","content":[{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/1.jpg","width":2048,"height":1536,"alt":"Stand Spice Events au Salon du Mariage"}},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Tenir un stand, ce n’est jamais “juste être là”","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Lors du dernier Salon du Mariage, l’équipe "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" était derrière le comptoir… mais aussi dans une multitude de rôles à la fois. Communication, organisation, coordination, relation clients… tout s’entremêlait. Mais avant même l’ouverture des portes, il y a eu toute une logistique invisible."}]},{"type":"paragraph","content":[{"type":"text","text":"L’équipe a d’abord imaginé le stand sur papier. Plans, croquis, organisation des espaces, placement du matériel, circulation des visiteurs… Tout a été dessiné, repensé, ajusté. Il a fallu mettre la main à la pâte en réalisant certains éléments soi-même."}]},{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/2.jpg","width":2400,"height":1800,"alt":"Montage du stand Spice Events au salon"}},{"type":"paragraph","content":[{"type":"text","text":"Puis est venu le pré-montage. "},{"type":"text","text":"Tester l’installation en amont, vérifier les volumes","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", l’équilibre visuel, la cohérence entre les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":", "},{"type":"text","text":"la technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" et l’identité "},{"type":"text","text":"Spice","marks":[{"type":"bold"}]},{"type":"text","text":". Monter, démonter, recommencer."}]},{"type":"paragraph","content":[{"type":"text","text":"Et bien sûr… les imprévus. Des éléments arrivés en retard. Certains détails à refaire. Des ajustements de dernière minute. Des décisions prises rapidement pour que tout reste fluide et professionnel. L’organisation du stand a été pensée, repensée, modifiée, optimisée. Parfois dans l’urgence mais toujours avec exigence."}]},{"type":"paragraph","content":[{"type":"text","text":"Mais cette préparation ne s’est pas limitée au stand physique."}]},{"type":"paragraph","content":[{"type":"text","text":"En amont, il a fallu imaginer et concevoir plusieurs designs : les brochures, les cartes de visite en forme de piment, les bâches de fond, les supports visuels… Chaque élément a été réfléchi pour créer une identité cohérente et immédiatement reconnaissable qui marque les esprits."}]},{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/3.jpg","width":2400,"height":1800,"alt":"Cartes de visite Spice Events en forme de piment"}},{"type":"paragraph","content":[{"type":"text","text":"Mais pour être honnête, tout a en réalité commencé bien avant le salon. L''équipe de "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" a mis toute son énergie pour se concentrer sur la remise en ligne du site "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" dans une nouvelle version, plus affirmée et plus structurée. Sur une nouvelle ligne éditoriale pour les réseaux sociaux, avec une identité plus claire, plus forte et plus fidèle à l’univers "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":"... En bref, de nombreux projets réalisés en peu de temps."}]},{"type":"paragraph","content":[{"type":"text","text":"Une préparation stratégique, pensée pour renforcer notre crédibilité et faciliter la navigation des visiteurs entre nos différentes plateformes."}]},{"type":"paragraph","content":[{"type":"text","text":"Le jour J, l’équipe "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" n’était plus simplement exposante. Elle incarnait l’énergie de ce merveilleux projet : expliquer les offres, orienter les "},{"type":"text","text":"futur(e)s marié(e)s","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" vers les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":", leur présenter l’univers "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" et assurer la cohérence globale."}]},{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/4.jpg","width":2400,"height":1800,"alt":"Livre d''or audio : téléphone rétro dans une valise vintage fleurie"}},{"type":"paragraph","content":[{"type":"text","text":"Créer une ambiance, ce n’est pas seulement installer du matériel ou mixer de la musique. C’est anticiper. Ajuster. Rebondir. Maintenir un niveau d’exigence même quand les choses ne se passent pas exactement comme prévu. C’est accepter que la préparation soit parfois plus intense que l’événement lui-même."}]},{"type":"paragraph","content":[{"type":"text","text":"Mais c’est aussi ce qui rend l’expérience forte. Voir le stand prendre vie après tant d’allers-retours. Voir les "},{"type":"text","text":"futur(e)s marié(e)s","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" s’arrêter, poser des questions, sourire. Voir une carte de visite en forme de piment marquer les esprits et amuser. Finalement, un stand réussi ressemble beaucoup à un événement réussi : de la préparation, de l’adaptation… et une équipe soudée derrière chaque détail."}]},{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/5.jpg","width":2400,"height":1800,"alt":"Bar à vinyles : platine et ardoise « Choisissez un vinyle, je le mixe pour vous »"}},{"type":"paragraph","content":[{"type":"text","text":"Toute cette préparation, cette anticipation, ces ajustements permanents, cette capacité à gérer les imprévus… c’est exactement ce que l’équipe "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" met au service des "},{"type":"text","text":"marié(e)s","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". Chaque détail pensé en amont, chaque solution trouvée en urgence, chaque choix stratégique a un seul objectif : vous garantir un mariage fluide, maîtrisé et inoubliable."}]},{"type":"paragraph","content":[{"type":"text","text":"Parce qu’un événement réussi repose sur la rigueur et un "},{"type":"text","text":"accompagnement personnalisé","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":". Et cette rigueur, "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" la mettra au cœur de votre "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" !"}]},{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/6.jpg","width":2400,"height":1800,"alt":"L''équipe Spice Events échange avec des visiteurs sur son stand"}},{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/7.jpg","width":2048,"height":1536,"alt":"Membre de l''équipe Spice Events devant le stand du salon"}},{"type":"image","attrs":{"src":"/journal/de-visiteurs-a-exposants-l-envers-du-decor-d-un-salon-du-mariage/8.jpg","width":1456,"height":2400,"alt":"Borne photobooth sur le stand du salon"}}]}'::jsonb
) on conflict do nothing;

-- guirlandes-lumineuses
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '0a1bb6d6-8590-500d-8aa7-c4cafedaf185', 'publie', '2025-12-18T12:00:00+01:00'::timestamptz, 'guirlandes-lumineuses',
  'Guirlandes lumineuses',
  'L’éclairage guinguette qui sublime vos événements',
  'Les guirlandes lumineuses, aussi appelées guirlandes guinguettes, se sont imposées comme un élément phare de la scénographie événementielle.',
  'Animations', '2025-12-18'::date,
  '/journal/guirlandes-lumineuses/couverture.jpg',
  'Dîner de mariage dans une grange sous un ciel de guirlandes lumineuses',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Les "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":", aussi appelées guirlandes guinguettes, se sont imposées comme un élément phare de la scénographie événementielle. Intemporelles et élégantes, elles offrent une lumière chaleureuse qui transforme instantanément un lieu et crée une atmosphère conviviale, festive et raffinée. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", nous les considérons comme bien plus qu’un simple éclairage : ce sont de véritables outils de mise en scène au service de l’émotion."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une lumière douce pour une ambiance unique"}]},{"type":"paragraph","content":[{"type":"text","text":"Contrairement à un éclairage classique, les "},{"type":"text","text":"guirlandes guinguettes","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" diffusent une lumière chaude et enveloppante. Elles invitent au partage, à la convivialité et à la détente. Que ce soit pour un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", une "},{"type":"text","text":"soirée privée ou un événement professionnel","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", elles apportent ce supplément d’âme qui rend un moment inoubliable. Leur esthétique simple et élégante s’adapte à tous les styles : champêtre, bohème, chic, moderne ou industriel."}]},{"type":"image","attrs":{"src":"/journal/guirlandes-lumineuses/1.jpg","width":534,"height":667,"alt":"Salle de réception en bois décorée de guirlandes guinguettes"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Structurer et habiller les espaces"}]},{"type":"paragraph","content":[{"type":"text","text":"Les "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" permettent également de structurer visuellement un lieu. Elles peuvent délimiter des zones, guider les invités ou mettre en valeur certains espaces clés de votre "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":". Installées en ciel étoilé au-dessus d’un dîner, tendues entre des arbres, fixées sur des structures ou intégrées à une tente, elles habillent les volumes et donnent une véritable identité à votre scénographie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un allié incontournable pour les mariages"}]},{"type":"paragraph","content":[{"type":"text","text":"Dans l’univers du "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", les "},{"type":"text","text":"guirlandes guinguettes","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" sont devenues un incontournable. Elles accompagnent parfaitement les moments forts : cocktail en extérieur, dîner sous les étoiles, ouverture de bal ou soirée dansante. Elles créent une atmosphère romantique et chaleureuse sans jamais voler la vedette aux mariés. Associées à d’autres éléments comme la sonorisation, l’éclairage décoratif ou les animations proposées par "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", elles participent à une mise en scène harmonieuse et élégante."}]},{"type":"image","attrs":{"src":"/journal/guirlandes-lumineuses/2.jpg","width":1080,"height":1350,"alt":"Mariés dansant sous des guirlandes lumineuses"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une solution élégante pour les événements professionnels ou privés"}]},{"type":"paragraph","content":[{"type":"text","text":"Les "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" trouvent également leur place lors "},{"type":"text","text":"d’événements d’entreprise","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":" ou soirées privées: soirées corporate, inaugurations, lancements de produits ou réceptions clients... Elles permettent d’adoucir un lieu, de le rendre plus accueillant et de créer une ambiance propice aux échanges. Elles sont idéales pour transformer un espace brut ou extérieur en un lieu chaleureux et valorisant pour votre image de marque."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une installation pensée dans les moindres détails"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", chaque installation de "},{"type":"text","text":"guirlandes","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" lumineuses est pensée sur mesure. Nous vous conseillons sur les meilleurs emplacements, les hauteurs, les tensions et la disposition afin d’obtenir un rendu esthétique et équilibré. Nos équipes assurent une installation sécurisée, soignée et parfaitement intégrée à l’ensemble de votre "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", en tenant compte des contraintes techniques et du lieu."}]},{"type":"image","attrs":{"src":"/journal/guirlandes-lumineuses/3.jpg","width":1000,"height":1000,"alt":"Salle de dîner sous voilages et guirlandes lumineuses"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’éclairage comme élément de scénographie globale"}]},{"type":"paragraph","content":[{"type":"text","text":"Les "},{"type":"text","text":"guirlandes guinguettes","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" prennent toute leur dimension lorsqu’elles s’intègrent dans une scénographie globale. Associées à un éclairage architectural, à une piste de danse, à une sonorisation adaptée ou à des animations visuelles, elles renforcent l’expérience immersive vécue par vos invités. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", nous concevons l’éclairage comme un fil conducteur qui accompagne chaque moment de votre événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une ambiance qui marque les esprits"}]},{"type":"paragraph","content":[{"type":"text","text":"Simples en apparence, les "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" ont un impact fort sur l’ambiance et les souvenirs laissés à vos invités. Elles créent une atmosphère chaleureuse, élégante et mémorable, idéale pour sublimer vos plus beaux instants. Faites confiance à "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" pour illuminer vos événements et transformer chaque lieu en un décor unique et inoubliable."}]}]}'::jsonb
) on conflict do nothing;

-- l-apres-evenement-ce-que-vos-invites-retiennent-de-votre-soiree-grace-a-une
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '12b6c358-87d1-56d4-aaaf-5cdcbed5d485', 'publie', '2026-03-04T12:00:00+01:00'::timestamptz, 'l-apres-evenement-ce-que-vos-invites-retiennent-de-votre-soiree-grace-a-une',
  'L’après-événement : ce que vos invités retiennent de votre soirée grâce à une technique bien pensée',
  'Tout est dans le détail',
  'On parle souvent du jour J, de la playlist parfaite ou encore de l’ouverture de bal.',
  'Technique', '2026-03-04'::date,
  '/journal/l-apres-evenement-ce-que-vos-invites-retiennent-de-votre-soiree-grace-a-une/couverture.jpg',
  'Atelier de matériel avec flight cases alignés',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On parle souvent du jour J, de la playlist parfaite ou encore de l’"},{"type":"text","text":"ouverture de bal","marks":[{"type":"link","attrs":{"href":"/animations/ouverture-de-bal"}}]},{"type":"text","text":". Pourtant, la véritable réussite d’un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou d’un événement se mesure souvent après coup. Dans les jours qui suivent, ce que retiennent réellement vos invités n’est pas un détail isolé, mais une impression globale : une ambiance, une énergie, une sensation de fluidité. C’est précisément là qu’une "},{"type":"text","text":"technique bien pensée","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" fait toute la différence."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La technique, fondation invisible de l’expérience"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", l’expérience nous montre qu’une soirée mémorable repose avant tout sur une "},{"type":"text","text":"préparation technique rigoureuse","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":". Lorsque "},{"type":"text","text":"le son, la lumière","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" et le déroulé sont parfaitement maîtrisés, tout paraît naturel aux yeux des invités. À l’inverse, le moindre déséquilibre technique peut casser la dynamique, même avec une excellente sélection musicale. La "},{"type":"text","text":"technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" n’est pas un simple support logistique : elle constitue la fondation invisible de l’expérience vécue ("},{"type":"text","text":"voir l’article : ","marks":[{"type":"italic"}]},{"type":"text","text":"Pourquoi la technique est invisible quand elle est bien faite ?","marks":[{"type":"link","attrs":{"href":"/journal/pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite"}},{"type":"italic"}]},{"type":"text","text":")."}]},{"type":"image","attrs":{"src":"/journal/l-apres-evenement-ce-que-vos-invites-retiennent-de-votre-soiree-grace-a-une/1.jpg","width":2048,"height":1433,"alt":"Câbles rangés et flight cases dans un atelier"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le rôle déterminant du son"}]},{"type":"paragraph","content":[{"type":"text","text":"Le son","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" est souvent le premier facteur déterminant. Un système audio bien calibré doit s’adapter aux différents temps de la soirée. Pendant le dîner, il doit permettre aux invités d’échanger confortablement tout en installant une atmosphère chaleureuse. Au moment des temps forts, il doit gagner en présence sans jamais devenir agressif. Enfin, sur la piste de danse, il doit délivrer une énergie claire et enveloppante qui donne envie de rester danser. Cette gestion fine des niveaux et des transitions demande une réelle expertise terrain et une lecture constante de la salle."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’impact visuel de la lumière"}]},{"type":"paragraph","content":[{"type":"text","text":"La lumière","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" joue également un rôle majeur dans la mémoire émotionnelle de vos invités. Avant même de se souvenir d’un morceau précis, ils retiennent une ambiance visuelle. Une "},{"type":"text","text":"mise en lumière cohérente","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" valorise le lieu de réception, accompagne les moments clés et soutient la montée en puissance de la soirée. Une lumière statique ou mal adaptée peut rapidement donner une impression plate, tandis qu’un éclairage évolutif crée une véritable dynamique. L’objectif n’est jamais d’en faire trop, mais de soutenir chaque moment avec justesse."}]},{"type":"image","attrs":{"src":"/journal/l-apres-evenement-ce-que-vos-invites-retiennent-de-votre-soiree-grace-a-une/2.jpg","width":2048,"height":1296,"alt":"Projecteurs rangés sur un portant"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La fluidité, véritable signature professionnelle"}]},{"type":"paragraph","content":[{"type":"text","text":"Au-delà du "},{"type":"text","text":"son et de la lumière","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", la fluidité du déroulé reste l’un des marqueurs les plus forts de professionnalisme. Lorsque tout s’enchaîne naturellement — les discours, "},{"type":"text","text":"les animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":", "},{"type":"text","text":"l’ouverture de bal","marks":[{"type":"link","attrs":{"href":"/animations/ouverture-de-bal"}}]},{"type":"text","text":", la soirée dansante — les invités perçoivent immédiatement la qualité de l’organisation. Cette impression de facilité est en réalité le fruit d’une coordination précise en amont et d’une capacité d’adaptation en temps réel. Anticiper les temps forts, communiquer avec les autres prestataires et ajuster le rythme de la soirée sont des éléments essentiels pour maintenir l’énergie collective."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une approche globale signée Spice Events"}]},{"type":"paragraph","content":[{"type":"text","text":"C’est pourquoi "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" adopte une vision globale de chaque événement. "},{"type":"text","text":"La technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", l’animation et la structure de la soirée sont pensées ensemble, jamais séparément. Cette approche permet non seulement de sécuriser le bon déroulement du jour J, mais surtout de maximiser l’impact émotionnel après l’événement. Car ce sont bien les retours des invités, les messages reçus le lendemain et les souvenirs partagés qui mesurent la réussite réelle d’une soirée."}]},{"type":"image","attrs":{"src":"/journal/l-apres-evenement-ce-que-vos-invites-retiennent-de-votre-soiree-grace-a-une/3.jpg","width":2048,"height":1365,"alt":"Entrepôt de matériel son et lumière"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Créer un souvenir qui dure"}]},{"type":"paragraph","content":[{"type":"text","text":"En définitive, une "},{"type":"text","text":"technique bien pensée","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" ne se voit pas toujours, mais elle se ressent durablement. Elle permet de créer une atmosphère immersive, de maintenir une piste de danse active et d’offrir une expérience cohérente du début à la fin. Pour les mariés comme pour leurs invités, c’est souvent ce niveau de maîtrise qui transforme une belle soirée en souvenir marquant."}]}]}'::jsonb
) on conflict do nothing;

-- le-role-du-dj-dans-le-timing-de-votre-evenement-bien-au-dela-de-la-musique
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '0f9afb29-9143-50c8-ab4a-b4703a8366c9', 'publie', '2026-01-13T12:00:00+01:00'::timestamptz, 'le-role-du-dj-dans-le-timing-de-votre-evenement-bien-au-dela-de-la-musique',
  'Le rôle du DJ dans le timing de votre événement (bien au-delà de la musique)',
  'L’art de maîtriser le temps pour sublimer chaque instant',
  'Lorsqu’on pense au DJ, on imagine avant tout la musique, l’ambiance et la piste de danse.',
  'Musique & ambiance', '2026-01-13'::date,
  '/journal/le-role-du-dj-dans-le-timing-de-votre-evenement-bien-au-dela-de-la-musique/couverture.jpg',
  'Régie DJ « Let''s Dance » éclairée en orange et violet',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lorsqu’on pense au DJ, on imagine avant tout la musique, l’ambiance et la piste de danse. Pourtant, lors d’un mariage ou d’un événement haut de gamme, le DJ joue un rôle bien plus large : il est le gardien du rythme global de la soirée. Un rôle discret, souvent invisible, mais absolument essentiel à la fluidité et à l’émotion de l’événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le DJ, chef d’orchestre du déroulé"}]},{"type":"paragraph","content":[{"type":"text","text":"Un événement réussi repose sur une succession de moments forts qui s’enchaînent naturellement. Entrée des mariés, discours, ouverture de bal, surprises, montée en puissance de la soirée… Le DJ est celui qui donne le tempo, en veillant à ce que chaque séquence arrive au bon moment, ni trop tôt, ni trop tard. Sans jamais s’imposer, il ajuste le rythme en temps réel pour éviter :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"les temps morts,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"les ruptures d’ambiance,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"les transitions brutales entre les différents moments clés."}]}]}]},{"type":"image","attrs":{"src":"/journal/le-role-du-dj-dans-le-timing-de-votre-evenement-bien-au-dela-de-la-musique/1.jpg","width":1200,"height":799,"alt":"Mains d''un DJ sur une table de mixage éclairée en bleu"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Créer des transitions fluides et naturelles"}]},{"type":"paragraph","content":[{"type":"text","text":"Le timing ne se résume pas à une heure sur un planning. Il s’agit avant tout de ressenti. Un bon DJ sait :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"prolonger un moment quand l’émotion est à son apogée,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"accélérer le rythme lorsque l’énergie du public le demande,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"préparer les invités à un temps fort sans jamais les brusquer."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"La musique devient alors un outil de narration, qui guide les invités tout au long de la soirée."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"S’adapter en permanence à l’énergie de la salle"}]},{"type":"paragraph","content":[{"type":"text","text":"Aucun événement ne se déroule exactement comme prévu. Le DJ est là pour lire la salle, observer les réactions, ressentir l’ambiance et ajuster le déroulé en conséquence. Un discours qui se prolonge, une piste de danse qui s’enflamme plus tôt que prévu, un moment d’émotion imprévu… Le DJ adapte le timing en temps réel pour que tout reste fluide, naturel et cohérent."}]},{"type":"image","attrs":{"src":"/journal/le-role-du-dj-dans-le-timing-de-votre-evenement-bien-au-dela-de-la-musique/2.jpg","width":736,"height":736,"alt":"Invités dansant sous des boules à facettes et des lasers"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sublimer les moments clés"}]},{"type":"paragraph","content":[{"type":"text","text":"Chaque temps fort mérite sa juste place. Le DJ intervient pour :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"annoncer ou accompagner les moments importants,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"créer l’attente avant une surprise ou une entrée,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"renforcer l’impact émotionnel par un choix musical précis."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ces détails font toute la différence entre une soirée qui s’enchaîne… et une soirée qui se vit pleinement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un timing maîtrisé pour une expérience sans stress"}]},{"type":"paragraph","content":[{"type":"text","text":"Lorsque le timing est bien géré, tout paraît simple. Les invités ne voient que l’évidence, la fluidité, le plaisir du moment. C’est justement là que réside le savoir-faire du DJ : faire oublier la technique et le déroulé, pour ne laisser place qu’à l’expérience. Chez Spice Events, nous considérons le DJ comme un véritable chef d’orchestre de l’événement, garant du rythme, de l’énergie et de l’émotion, du premier instant jusqu’au dernier morceau. Parce qu’un bon événement ne se contente pas de sonner juste…il se vit au bon moment."}]}]}'::jsonb
) on conflict do nothing;

-- les-plus-beaux-lieux-pour-un-mariage-hivernal
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '62051a50-86be-5321-9d1e-3d1123c3b585', 'publie', '2022-02-01T12:00:00+01:00'::timestamptz, 'les-plus-beaux-lieux-pour-un-mariage-hivernal',
  'Les plus beaux lieux pour un mariage hivernal',
  'Faites-vous rêver',
  'Vous souhaitez vous marier en hiver mais vous ne savez pas où organiser votre réception ?',
  'Conseils mariage', '2022-02-01'::date,
  '/journal/les-plus-beaux-lieux-pour-un-mariage-hivernal/couverture.jpg',
  'Salle de bal décorée de guirlandes et d''un sapin de Noël',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vous souhaitez vous marier en hiver mais vous ne savez pas où organiser votre réception ? Spice a trouvé pour vous 3 idées de lieux pour un mariage hivernal réussi."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Au bord d’un lac"}]},{"type":"paragraph","content":[{"type":"text","text":"Si vous recherchez un cadre idyllique et magique, pourquoi ne pas louer une salle ou un hôtel situé au bord d’un lac ? En hiver, les lacs nous offrent un spectacle fabuleux et d’autant plus s’ils sont gelés. Un bon moyen d’impressionner vos invités et leur proposer un mariage différent qui marquera les esprits. Avec une vue pareille, vous pourrez prendre de jolies photos originales à l’aide de notre "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Pensez également à "},{"type":"text","text":"éclairer","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" l’extérieur de votre lieu, pour que même une fois la nuit tombée, le lac reste visible."}]},{"type":"paragraph","content":[{"type":"text","text":"Photo : "},{"type":"text","text":"Salle du Domaine du Baron de Montriond","marks":[{"type":"link","attrs":{"href":"https://www.salledudomainedubaron.com/"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Dans un chalet à la montagne"}]},{"type":"paragraph","content":[{"type":"text","text":"Vous êtes fans de ski, de randonnée ou tout simplement de la montagne en elle-même? Alors vous marier dans un joli chalet est une évidence. Au calme, dans un endroit reculé, vous pourrez profiter pleinement de vos proches et du cadre qui s’offre à vous."}]},{"type":"paragraph","content":[{"type":"text","text":"Un chalet est un lieu convivial et chaleureux qui apportera de l''intimité à votre mariage."}]},{"type":"paragraph","content":[{"type":"text","text":"Ajoutez à cela "},{"type":"text","text":"un orchestre","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" et le tour est joué pour séduire vos invités, déjà charmés par ce lieu insolite."}]},{"type":"paragraph","content":[{"type":"text","text":"Photo : "},{"type":"text","text":"Chalet Chateau Alyma","marks":[{"type":"link","attrs":{"href":"https://www.monsieurchalets.com/en-ca/chalets-a-louer/laurentides/chalet-a-louer-corporatif-chateaualyma-966"}}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un lieu avec cheminée"}]},{"type":"paragraph","content":[{"type":"text","text":"Qui dit hiver, dit cheminée. Et cet élément hivernal pourrait être l’objet de décoration phare de votre lieu de réception. Avec elle, le chaleureux et la convivialité seront au rendez-vous."}]},{"type":"paragraph","content":[{"type":"text","text":"Ajoutez-y des éléments de décoration en fonction de votre thématique et rendez ce moment cosy et rempli de charme."}]},{"type":"paragraph","content":[{"type":"text","text":"Photo : "},{"type":"text","text":"Les Hauts de Pardaillan","marks":[{"type":"link","attrs":{"href":"http://www.leshautsdepardaillan.com/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Maintenant que vous savez où célébrer votre mariage, rendez-vous sur notre site afin de découvrir nos "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" tendances et rendre ce moment encore plus inoubliable."}]}]}'::jsonb
) on conflict do nothing;

-- les-plus-belles-chansons-pour-ouvrir-le-bal
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'ba01fae6-b80b-51f1-9e6b-92c85ec4b4b1', 'publie', '2022-02-22T12:00:00+01:00'::timestamptz, 'les-plus-belles-chansons-pour-ouvrir-le-bal',
  'Les plus belles chansons pour ouvrir le bal',
  'd''après Spice Events',
  'En manque d’inspiration pour trouver LA chanson parfaite pour votre ouverture de bal ?',
  'Musique & ambiance', '2022-02-22'::date,
  '/journal/les-plus-belles-chansons-pour-ouvrir-le-bal/couverture.jpg',
  'Mariés main dans la main pour leur première danse',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"En manque d’inspiration pour trouver LA chanson parfaite pour votre ouverture de bal ? Spice Events a répertorié pour vous les plus belles musiques pour ce moment magique !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. A Thousand Years de Christina Perri"}]},{"type":"paragraph","content":[{"type":"text","text":"Pour les fans de Twilight (mais aussi pour les autres) cette chanson est un symbole du véritable amour. Alors si comme Bella et Edward, votre amour est plus fort que tout, cette chanson est faite pour vous."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Thinking Out Loud d’Ed Sheeran"}]},{"type":"paragraph","content":[{"type":"text","text":"Si on regarde la traduction de cette chanson d’Ed Sheeran, les paroles sont parfaites pour un mariage et notamment pour une ouverture de bal. Une très belle façon de déclarer sa flamme en laissant la parole à notre chanteur anglo saxon préféré."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Je te promets de Johnny Hallyday"}]},{"type":"paragraph","content":[{"type":"text","text":"Un peu de français avec ce grand chanteur et compositeur qui n’est d’autre que Johnny Hallyday. Avec sa chanson “Je te promets”, la douceur et le romantisme seront au rendez-vous, pour une ouverture tout en émotion."}]},{"type":"image","attrs":{"src":"/journal/les-plus-belles-chansons-pour-ouvrir-le-bal/1.jpg","width":2400,"height":1600,"alt":"Mariés enlacés sous des guirlandes lumineuses"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Love Me Like You Do d'' Ellie Goulding"}]},{"type":"paragraph","content":[{"type":"text","text":"Si vous souhaitez un peu plus de rythme pour pouvoir montrer vos grands talents de danse, optez pour cette chanson plus dynamique mais toujours très romantique d’Ellie Goulding. Encore un morceau rempli d’amour et de promesse."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Je l’aime à mourir de Francis Cabrel"}]},{"type":"paragraph","content":[{"type":"text","text":"Un peu plus ancienne que les autres musiques que nous vous avons proposées jusqu''ici, cette jolie chanson écrite par Francis Cabrel est une belle déclaration pour votre conjoint/e en ce jour si particulier."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"6. Just The Way You Are de Bruno Mars"}]},{"type":"paragraph","content":[{"type":"text","text":"Si vous et votre moitié vous vous aimez “just the way you are”, remerciez notre cher Bruno Mars pour ce single et empruntez-lui juste le temps d’une danse."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"7. All of me de John Legend"}]},{"type":"paragraph","content":[{"type":"text","text":"Autre très belle chanson symbole d’amour et de dévotion, cette chanson du talentueux John Legend qui saura vous emporter dans un moment magique et inoubliable."}]},{"type":"image","attrs":{"src":"/journal/les-plus-belles-chansons-pour-ouvrir-le-bal/2.jpg","width":2400,"height":1620,"alt":"Mariés enlacés sous des suspensions en osier lumineuses"}},{"type":"paragraph","content":[{"type":"text","text":"A vous de faire votre choix !"}]},{"type":"paragraph","content":[{"type":"text","text":"Sans oublier que Spice Events vous propose également un "},{"type":"text","text":"booking DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" pour lancer la playlist que vous choisirez."}]}]}'::jsonb
) on conflict do nothing;

-- livre-d-or-audio
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'e1ebd294-c7c5-5d83-a572-3310951a25a8', 'publie', '2025-12-05T12:00:00+01:00'::timestamptz, 'livre-d-or-audio',
  'Livre d’or audio',
  'Quand les souvenirs prennent vie avec Spice Events',
  'Dans l’univers des mariages et événements, chaque détail compte pour créer des souvenirs mémorables.',
  'Animations', '2025-12-05'::date,
  '/journal/livre-d-or-audio/couverture.jpg',
  'Livre d''or audio : téléphone blanc et panneau « Audio Guestbook »',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dans l’univers des "},{"type":"text","text":"mariages","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" et "},{"type":"text","text":"événements","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", chaque détail compte pour créer des souvenirs mémorables. Spice Events vous propose son livre d’or audio qui transforme la traditionnelle page de signatures en une expérience sonore unique. Plus qu’un simple objet, il permet à vos invités de partager leurs émotions, anecdotes et messages personnels… et de les réécouter à l’infini."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Qu’est-ce qu’un livre d’or audio ?"}]},{"type":"paragraph","content":[{"type":"text","text":"Le concept est simple et magique ! Un combiné téléphonique ou un micro est installé lors de votre "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", permettant à vos convives de laisser un message vocal. Ces enregistrements capturent l’authenticité des émotions, les rires, les mots sincères et les encouragements, offrant un souvenir vivant et vibrant. Pour plus de style et d’originalité, le "},{"type":"text","text":"livre d’or audio","marks":[{"type":"link","attrs":{"href":"/animations/livre-d-or-audio"}}]},{"type":"text","text":" peut être intégré dans une cabine personnalisée ou même dans une valise vintage, apportant une touche rétro et ludique à votre événement."}]},{"type":"image","attrs":{"src":"/journal/livre-d-or-audio/1.jpg","width":1200,"height":1800,"alt":"Téléphone rétro du livre d''or audio posé sur une table"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pourquoi opter pour un livre d’or audio avec Spice Events ?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Un souvenir vivant et émotionnel : Vous entendrez les voix de vos proches et l’émotion derrière chaque mot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fun et interactif : Vos invités s’amusent à laisser des messages, des anecdotes ou même des chansons."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Facile à utiliser : Il suffit de décrocher le combiné ou de parler dans le micro. Les messages sont automatiquement enregistrés et peuvent être écoutés à tout moment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Personnalisable : vous pouvez installer le "},{"type":"text","text":"livre d’or audio","marks":[{"type":"link","attrs":{"href":"/animations/livre-d-or-audio"}}]},{"type":"text","text":" dans une cabine téléphonique entièrement personnalisée selon vos envies ou alors le placer dans une valise vintage pour ravir les yeux de vos invités."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Comment l’utiliser lors de votre mariage ou événement ?"}]},{"type":"paragraph","content":[{"type":"text","text":"Installez-le dans un coin dédié et facilement accessible à vos invités, par exemple près du "},{"type":"text","text":"photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":", dans une cabine personnalisée ou sur une valise vintage. Avec quelques instructions simples, vos convives laisseront spontanément des messages authentiques, créant une compilation unique de souvenirs à chérir pour toujours."}]},{"type":"image","attrs":{"src":"/journal/livre-d-or-audio/2.jpg","width":595,"height":793,"alt":"Téléphone rétro du livre d''or audio face à la mer"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une alternative moderne et émotionnelle"}]},{"type":"paragraph","content":[{"type":"text","text":"Le "},{"type":"text","text":"livre d’or audio","marks":[{"type":"link","attrs":{"href":"/animations/livre-d-or-audio"}}]},{"type":"text","text":" de Spice Events est l’alternative parfaite au livre classique. Il combine émotion, originalité et interactivité, et permet de conserver des instants précieux sous une forme vivante. Que ce soit pour un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou un "},{"type":"text","text":"événement professionnel","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":" marquant, il crée un souvenir inoubliable, bien au-delà de ce qu’une simple page de signatures pourrait transmettre."}]}]}'::jsonb
) on conflict do nothing;

-- mariage-c-n-au-chateau-de-sauveboeuf
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '6d1e8570-f54c-588f-a8dc-28064af6c207', 'publie', '2019-08-27T12:00:00+02:00'::timestamptz, 'mariage-c-n-au-chateau-de-sauveboeuf',
  'Mariage C&N au Château de Sauveboeuf',
  null,
  'Encore une belle cérémonie sous le signe de l''amour pour Spice Events.',
  'Mariages réalisés', '2019-08-27'::date,
  '/journal/mariage-c-n-au-chateau-de-sauveboeuf/couverture.jpg',
  'Façade et pelouse du château de Sauveboeuf',
  '{"type":"doc","content":[{"type":"image","attrs":{"src":"/journal/mariage-c-n-au-chateau-de-sauveboeuf/1.jpg","width":2400,"height":1800,"alt":"Château de Sauveboeuf vu depuis l''allée d''entrée"}},{"type":"paragraph","content":[{"type":"text","text":"Encore une belle cérémonie sous le signe de l''amour pour Spice Events. Nos flight cases se sont installés dans le magnifique château de Sauveboeuf datant du XVIIᵉ siècle, en Dordogne."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour accompagner cette décoration champêtre, nos équipes se sont chargées de la sonorisation de la cérémonie religieuse. La sonorisation de votre cérémonie est un atout essentiel pour le bon déroulement de celle-ci : elle permet aux personnes du fond d''entendre de façon claire vos discours, d''avoir une musique sans grésillement & apporte une réelle qualité sonore pour vos animations."}]},{"type":"paragraph","content":[{"type":"text","text":"Nous avons également éclairé le repas avec des projecteurs LED sur batterie BOXKOLOR de la marque CHAUVET. Ces projecteurs offrent une ambiance champêtre et chaleureuse, qui s''inscrit parfaitement dans la thématique choisie par nos deux mariés."}]},{"type":"paragraph","content":[{"type":"text","text":"Le repas quant à lui était sonorisé avec 4 enceintes LD Systems MAUI5GO. Ces enceintes design se dissimulent parfaitement dans le décor, se rendant presque invisibles."}]},{"type":"paragraph","content":[{"type":"text","text":"La soirée se déroulait dans la pièce du bas et a duré jusqu’à 5h du matin."}]},{"type":"image","attrs":{"src":"/journal/mariage-c-n-au-chateau-de-sauveboeuf/2.jpg","width":2400,"height":1800,"alt":"Dîner de mariage dans une salle du château éclairée en lumière chaude"}}]}'::jsonb
) on conflict do nothing;

-- mariage-de-s-r-au-chateau-d-hardricourt
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'a3624bb0-443d-5083-8522-7a9effd0995b', 'publie', '2021-08-25T12:00:00+02:00'::timestamptz, 'mariage-de-s-r-au-chateau-d-hardricourt',
  'Mariage de S&R au château d’Hardricourt',
  'Un mariage aux allures féeriques',
  'C’est avec le plus grand plaisir que Spice Events est une nouvelle fois le prestataire technique de nos mariés, pour sublimer leur journée !',
  'Mariages réalisés', '2021-08-25'::date,
  '/journal/mariage-de-s-r-au-chateau-d-hardricourt/couverture.jpg',
  'Château d''Hardricourt illuminé par des projections bleues',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C’est avec le plus grand plaisir que Spice Events est une nouvelle fois le prestataire technique de nos mariés, pour sublimer leur journée !"}]},{"type":"paragraph","content":[{"type":"text","text":"Cette fois-ci, c’est pour le mariage de S&R que nos équipes ont pu intervenir pour "},{"type":"text","text":"la sonorisation, l’éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" architectural du château d’Hardricourt."}]},{"type":"paragraph","content":[{"type":"text","text":"Un mariage aux allures féeriques et qui a su émerveiller les convives dès leurs arrivées grâce aux projections lumineuses sur le Château d''Hardricourt, datant du XVIIIe siècle. Le mapping vidéo est une technologie multimédia permettant de projeter de la lumière ou des vidéos sur des volumes, de recréer des images de grande taille sur des structures en relief, tels des monuments, ou de recréer des univers à 360°."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour plus d''information concernant cette ","marks":[{"type":"bold"}]},{"type":"text","text":"technique événementielle","marks":[{"type":"link","attrs":{"href":"/a-propos"}},{"type":"bold"}]},{"type":"text","text":", n''hésitez pas à ","marks":[{"type":"bold"}]},{"type":"text","text":"nous contacter","marks":[{"type":"link","attrs":{"href":"/contact"}},{"type":"bold"}]},{"type":"text","text":"."}]}]}'::jsonb
) on conflict do nothing;

-- mariage-l-m-pres-de-massiac
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '68319fe9-9fd6-571d-beb3-9f4b4280a27f', 'publie', '2019-08-13T12:00:00+02:00'::timestamptz, 'mariage-l-m-pres-de-massiac',
  'Mariage L&M près de Massiac',
  'Un mariage sur le thème champêtre',
  'Encore un mariage qui se déroule comme sur des roulettes ! C''est près de Massiac que s''est déroulé un mariage 100% champêtre aux allures de paradis.',
  'Mariages réalisés', '2019-08-13'::date,
  '/journal/mariage-l-m-pres-de-massiac/couverture.jpg',
  'Coin détente champêtre avec scooter vintage dans le jardin',
  '{"type":"doc","content":[{"type":"image","attrs":{"src":"/journal/mariage-l-m-pres-de-massiac/1.jpg","width":2400,"height":1800,"alt":"Coin détente champêtre avec scooter vintage dans le jardin"}},{"type":"image","attrs":{"src":"/journal/mariage-l-m-pres-de-massiac/2.jpg","width":2400,"height":1800,"alt":"Invités réunis dans la cour d''une maison de campagne"}},{"type":"image","attrs":{"src":"/journal/mariage-l-m-pres-de-massiac/3.jpg","width":2400,"height":1800,"alt":"Tente du dîner éclairée à la nuit tombée"}},{"type":"image","attrs":{"src":"/journal/mariage-l-m-pres-de-massiac/4.jpg","width":1800,"height":2400,"alt":"Lanternes en papier colorées suspendues"}},{"type":"image","attrs":{"src":"/journal/mariage-l-m-pres-de-massiac/5.jpg","width":2400,"height":1800,"alt":"Cour de la maison mise en lumière la nuit"}},{"type":"image","attrs":{"src":"/journal/mariage-l-m-pres-de-massiac/6.jpg","width":900,"height":1200,"alt":"Arbre mis en lumière en rose et violet"}},{"type":"image","attrs":{"src":"/journal/mariage-l-m-pres-de-massiac/7.jpg","width":2400,"height":1800,"alt":"Lettres lumineuses « BAR » sur un mur éclairé en bleu"}},{"type":"paragraph","content":[{"type":"text","text":"Encore un mariage qui se déroule comme sur des roulettes ! C''est près de Massiac que s''est déroulé un mariage 100% champêtre aux allures de paradis."}]},{"type":"paragraph","content":[{"type":"text","text":"Après un cocktail dans la cour de leur maison de campagne familiale, les mariés ont profité d''un repas sous une tente éclairée grâce à des guirlandes lumineuses. Ces guirlandes décoratives confèrent une atmosphère chaleureuse et romantique. Nous avons sonorisé le repas avec une paire d''enceintes LD Systems MAUI5GO et des micros sans fils Shure. Grâce à son design sorti tout droit d''un film futuriste, ces enceintes sont passées inaperçues dans le décor."}]},{"type":"paragraph","content":[{"type":"text","text":"Nous en avons profité pour mettre en valeur la cour de la maison avec un ensemble de 12 projecteurs LED sur batterie WellFit de la marque CHAUVET afin de créer une ambiance intimiste."}]},{"type":"paragraph","content":[{"type":"text","text":"La partie dansante se déroulait dans la grange aménagée pour l''occasion. Nous avons sonorisé cet espace avec un système son L-ACOUSTICS SB18 et X12. Les éclairages de la piste de danse étaient des projecteurs ROBE Pointe et des par LED Contest. De quoi mettre en lumière chaque danseur !"}]},{"type":"paragraph","content":[{"type":"text","text":"Encore une soirée inoubliable pour des mariés au top !"}]}]}'::jsonb
) on conflict do nothing;

-- mariage-pluvieux-mariage-heureux
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'bf85df57-dce6-54b4-9fc2-e263325823d8', 'publie', '2021-12-07T12:00:00+01:00'::timestamptz, 'mariage-pluvieux-mariage-heureux',
  'Mariage pluvieux, mariage heureux ?',
  'Abritez-vous sous les conseils de Spice Events',
  'Un mariage ça se prévoit à l’avance et on ne peut pas prédire le temps qu’il fera.',
  'Conseils mariage', '2021-12-07'::date,
  '/journal/mariage-pluvieux-mariage-heureux/couverture.jpg',
  'Mariés s''embrassant sous un parapluie transparent',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Un mariage ça se prévoit à l’avance et on ne peut pas prédire le temps qu’il fera. Alors si par malchance, le jour venu, le soleil n’est pas au rendez-vous, pas de panique !"}]},{"type":"paragraph","content":[{"type":"text","text":"Spice Events vous donne toutes les solutions contre une météo capricieuse."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Miser sur la décoration intérieure"}]},{"type":"paragraph","content":[{"type":"text","text":"Vous allez passer la plus grande partie de votre journée à l’intérieur, alors autant qu’il soit agréable à regarder ! Cette année, de nouvelles tendances déco font leur apparition, telles que le bois, le végétal ou le noir. Il ne vous reste plus qu’à choisir celle que vous préférez."}]},{"type":"paragraph","content":[{"type":"text","text":"Évidemment, si vous souhaitez rester sobre, élégant et traditionnel, vous pouvez également choisir une thématique pour l’indémodable blanc."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour habiller votre salle, optez pour la "},{"type":"text","text":"mise en lumière","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" : jeux de couleurs et projections de motifs donnent vie à votre lieu et émerveillent vos invités. Encore une fois, le choix vous appartient en ce qui concerne le motif projeté."}]},{"type":"paragraph","content":[{"type":"text","text":"Autre tendance de cette année, les lettres lumineuses. Ces grandes lettres embelliront votre pièce et mettront en avant la lettre, le mot ou la phrase que vous souhaitez. C’est aussi un fond parfait pour de jolies photos souvenirs !"}]},{"type":"image","attrs":{"src":"/journal/mariage-pluvieux-mariage-heureux/1.jpg","width":2400,"height":1600,"alt":"Table de mariage décorée de fleurs et de verdure"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choisir les bonnes animations"}]},{"type":"paragraph","content":[{"type":"text","text":"Comme la soirée se passe à l’intérieur, il y a tout intérêt à avoir un bon DJ à ses côtés ! Allez jeter un coup d''œil à la liste de "},{"type":"text","text":"nos DJ d''exception","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", qui, nous le savons, seront à la hauteur de vos exigences musicales."}]},{"type":"paragraph","content":[{"type":"text","text":"Si vous souhaitez faire participer vos proches dans le choix des musiques, optez pour notre "},{"type":"text","text":"bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":". Une animation intergénérationnelle et vintage qui laisse place à la convivialité."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour occuper vos invités, comptez sur notre animation "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":". Accompagné d’accessoires, il fera l’unanimité. Amusant, distrayant et rempli de souvenirs, c’est l’animation à avoir absolument !"}]},{"type":"image","attrs":{"src":"/journal/mariage-pluvieux-mariage-heureux/2.jpg","width":1920,"height":1080,"alt":"Invités qui posent devant une borne photobooth"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Divertir vos invités"}]},{"type":"paragraph","content":[{"type":"text","text":"Engager un magicien est un bon moyen de divertir vos invités. Grâce à ses tours, il saura amuser et épater les petits comme les grands. Qu’il fasse son apparition lors du cocktail, du repas ou de la soirée, c’est une bonne alternative pour remédier à une mauvaise météo."}]},{"type":"paragraph","content":[{"type":"text","text":"Faire appel à un groupe de danse est aussi une bonne idée. Au moment que vous avez choisi, laissez-leur la piste et admirez."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour un effet “waouh”, Spice Events vous propose une "},{"type":"text","text":"ouverture de bal spectaculaire","marks":[{"type":"link","attrs":{"href":"/animations/ouverture-de-bal"}}]},{"type":"text","text":" avec étincelles froides et de la fumée lourde pour apporter une touche de magie à votre soirée."}]},{"type":"image","attrs":{"src":"/journal/mariage-pluvieux-mariage-heureux/3.jpg","width":1920,"height":1080,"alt":"Danseuses de samba en costume"}},{"type":"paragraph","content":[{"type":"text","text":"Et voilà, vous avez maintenant toutes les cartes en main pour occuper vos invités, coincés à l’intérieur à cause de la météo !"}]},{"type":"paragraph","content":[{"type":"text","text":"Mais "},{"type":"text","text":"si toutefois vous avez d’autres questions, n’hésitez pas à nous contacter","marks":[{"type":"link","attrs":{"href":"/contact"}}]},{"type":"text","text":"."}]}]}'::jsonb
) on conflict do nothing;

-- nos-astuces-pour-trouver-le-lieu-de-mariage-ideal
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'b712656e-ee99-5795-ba74-f3fbb5ae122d', 'publie', '2022-04-27T12:00:00+02:00'::timestamptz, 'nos-astuces-pour-trouver-le-lieu-de-mariage-ideal',
  'Nos astuces pour trouver le lieu de mariage idéal',
  null,
  'La recherche du lieu fait partie de la liste d''organisation d’un mariage.',
  'Conseils mariage', '2022-04-27'::date,
  '/journal/nos-astuces-pour-trouver-le-lieu-de-mariage-ideal/couverture.jpg',
  'Salle de réception aux murs de pierre avec projection lumineuse',
  '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Parce que chaque détail compte"}]},{"type":"paragraph","content":[{"type":"text","text":"La recherche du lieu fait partie de la liste d''organisation d’un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". C’est même le prestataire à trouver en priorité car sans lui, c’est tout le reste de l’organisation qui est mis en difficulté. Mais il est parfois compliqué de se fixer des critères. Spice Events vous "},{"type":"text","text":"accompagne","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" à chaque étape de votre grand jour !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une bonne accessibilité"}]},{"type":"paragraph","content":[{"type":"text","text":"L’accessibilité doit quoiqu’il arrive être dans vos critères. Que ce soit pour vous, pour vos invités ou vos "},{"type":"text","text":"prestataires","marks":[{"type":"link","attrs":{"href":"/"}}]},{"type":"text","text":", il est préférable de disposer d’un lieu facile d’accès pour ne pas les perdre. Vos invités trouveront plus facilement et vos prestataires pourront mieux y accéder avec leurs véhicules, parfois imposants."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Aéré et lumineux"}]},{"type":"paragraph","content":[{"type":"text","text":"Pour mettre en valeur votre thématique blanche, noire, bois ou végétale, vous devez disposer d’un lieu lumineux et aéré. De manière à ce que votre décoration ressorte quand le jour est encore présent et qu’une fois la nuit tombée, vos invités puissent encore en profiter et ce grâce à de jolies "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":"."}]},{"type":"image","attrs":{"src":"/journal/nos-astuces-pour-trouver-le-lieu-de-mariage-ideal/1.jpg","width":2048,"height":1365,"alt":"Mariés s''embrassant sous des guirlandes lumineuses, en noir et blanc"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une belle et grande salle de réception"}]},{"type":"paragraph","content":[{"type":"text","text":"Faites-vous rêver comme dans les films avec une majestueuse salle de réception, au volume époustouflant ! Évidemment dans la limite du raisonnable et de votre budget. Mais essayez de tout miser sur votre salle principale, ce qui parait logique car c’est dans celle-ci que vous allez passer tout votre temps."}]},{"type":"paragraph","content":[{"type":"text","text":"Le but étant de pouvoir y mettre en avant le plus possible votre thématique mais aussi de mettre en place des "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":". Vous pourrez y installer un "},{"type":"text","text":"photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":", un "},{"type":"text","text":"bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":", faire intervenir un groupe de jazz ou encore une troupe de danse !"}]},{"type":"paragraph","content":[{"type":"text","text":"Un grand espace permettra également une meilleure diffusion de la musique et un "},{"type":"text","text":"bel éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Isolé mais pas trop !"}]},{"type":"paragraph","content":[{"type":"text","text":"Idéalement, votre lieu doit être un peu à l’écart pour pouvoir profiter au maximum de votre "},{"type":"text","text":"ambiance musicale","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" sans avoir peur de déranger qui que ce soit. Et inversement, vous ne serez pas embêté par des voisins trop envahissants. Pensez à vérifier que le lieu de votre mariage n''est pas équipé de limiteurs sonores au risque d''altérer la qualité de la prestation."}]},{"type":"paragraph","content":[{"type":"text","text":"Attention à ne pas être trop isolé tout de même car comme dit précédemment, votre lieu doit rester accessible à tous !"}]},{"type":"image","attrs":{"src":"/journal/nos-astuces-pour-trouver-le-lieu-de-mariage-ideal/2.jpg","width":2048,"height":1365,"alt":"Invités dansant sous des guirlandes lumineuses"}},{"type":"paragraph","content":[{"type":"text","text":"Si vous avez besoin de plus d’informations ou de "},{"type":"text","text":"conseils","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":", n''hésitez pas à "},{"type":"text","text":"nous contacter","marks":[{"type":"link","attrs":{"href":"/contact"}}]},{"type":"text","text":", nous nous ferons un plaisir de vous aider !"}]}]}'::jsonb
) on conflict do nothing;

-- nos-idees-de-decoration-pour-vos-tables-de-mariage
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'b6c819a6-4c95-512c-a6d2-907d3a078ff4', 'publie', '2022-07-07T12:00:00+02:00'::timestamptz, 'nos-idees-de-decoration-pour-vos-tables-de-mariage',
  'Nos idées de décoration pour vos tables de mariage',
  'A table !',
  'Vous avez enfin trouvé votre lieu, votre traiteur et votre DJ ? C’est le moment d’imaginer votre décoration.',
  'Conseils mariage', '2022-07-07'::date,
  '/journal/nos-idees-de-decoration-pour-vos-tables-de-mariage/couverture.jpg',
  'Table dressée de nappes blanches et de compositions florales',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vous avez enfin trouvé votre lieu, votre traiteur et votre "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ? C’est le moment d’imaginer votre décoration. Des murs jusqu’à l''assiette, celle-ci ne doit pas être négligée, d’autant plus que vos invités vont passer la majeure partie de leur soirée à table."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une décoration blanche tu aimeras"}]},{"type":"paragraph","content":[{"type":"text","text":"Le blanc c’est LA “couleur” du mariage. Synonyme de pureté, on la retrouve très souvent dans la décoration des mariages. C’est une couleur qui plaira toujours mais si vous voulez que vos invités soient vraiment subjugués, il faut vous démarquer et l''utiliser de façon originale. En l’associant à une autre couleur ou avec du bois, vous obtiendrez un joli mélange raffiné. Vous pouvez utiliser un chemin de table en dentelle blanche, de la vaisselle ancienne, des couverts dorés, placer des lettres lumineuses sur la table du buffet, mettre de grandes "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" suspendues au-dessus des tables ou encore ajouter de la couleur en dépareillant les fauteuils des mariés."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une touche végétale tu apprécieras"}]},{"type":"paragraph","content":[{"type":"text","text":"En misant sur une thématique remplie de plantes et de fleurs, vous tombez pile dans la tendance ! Utilisez des bouteilles en verre pour vos fleurs ou comme bocal à "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":", prenez des rondins de bois en guise de sous-assiette ou pour placer vos décorations de centre de table. Pour le plaçage, écrivez les prénoms de vos invités sur des piquets à potager et plantez-les dans de beaux pots accompagnés d''une plante ou accrochez d''adorables étiquettes sur un petit bouquet de fleurs séchées. Pour votre centre de table, installez une petite jardinière ou un bouquet XL mais attention à la hauteur, c''est mieux si vos convives peuvent voir leurs voisins d’en face. Disposez de la pampa et des chandeliers c’est très tendance."}]},{"type":"paragraph","content":[{"type":"text","text":"Il est préférable de privilégier les plantes fraîches pour plus de classe et d''élégance mais si vous n''avez pas le budget, il existe aujourd’hui de très jolies alternatives. Vous pouvez également mélanger les deux. Si vous faites le choix de vraies plantes, évitez également les fleurs et plantes trop odorantes qui pourraient déranger vos invités."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le noir tu considéreras"}]},{"type":"paragraph","content":[{"type":"text","text":"Moins traditionnel que le blanc, le noir fonctionne aussi très bien pour la décoration de mariage. Il est plus rare d’en voir et c''est pour cela qu’il est intéressant de l''utiliser. Si vous le disposez correctement, vous êtes sûrs d’épater vos invités. Pour cela, vous pouvez par exemple, mettre un long chemin de table et le laisser tomber jusqu''au sol, disperser des éléments en cuivre, ajouter de la couleur avec des fleurs et des plantes et pourquoi ne pas ajouter des objets d’animation comme un porte photo où vos invités pourront accrocher leurs jolis clichés pris dans la journée grâce à votre "},{"type":"text","text":"photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":" ?"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Des éléments bois tu affectionneras"}]},{"type":"paragraph","content":[{"type":"text","text":"Très tendance, le bois se révèle. Son avantage est qu’il se fond avec tous types de décoration. Pour lui apporter plus de couleur et de gaieté, vous pouvez dépareiller vos verres mais attention à ne pas trop faire de mélange et de donner dans le too much, rester dans les mêmes tons et styles de couleurs. Si vous avez prévu de grandes tables en bois, n’y mettez pas de nappe et de cette façon, elle sera mise en valeur. Choisissez de jolies chaises ou un grand banc et placez-y des coussins de couleurs pour apporter chaleur et convivialité. Vous pouvez aussi mélanger plusieurs styles de chaises."}]},{"type":"paragraph","content":[{"type":"text","text":"Afin d''illustrer nos idées, voici quelques inspirations","marks":[{"type":"bold"}]},{"type":"text","text":" :"}]},{"type":"image","attrs":{"src":"/journal/nos-idees-de-decoration-pour-vos-tables-de-mariage/1.jpg","width":2400,"height":1603,"alt":"Assiette ancienne et serviette rose sur une table de mariage"}},{"type":"image","attrs":{"src":"/journal/nos-idees-de-decoration-pour-vos-tables-de-mariage/2.jpg","width":2400,"height":1600,"alt":"Table de mariage décorée de fleurs et de verdure"}},{"type":"image","attrs":{"src":"/journal/nos-idees-de-decoration-pour-vos-tables-de-mariage/3.jpg","width":2400,"height":1606,"alt":"Table de mariage avec centre de table fleuri et verres colorés"}},{"type":"image","attrs":{"src":"/journal/nos-idees-de-decoration-pour-vos-tables-de-mariage/4.jpg","width":2400,"height":1478,"alt":"Table décorée de bougies, de tulipes et de vaisselle ancienne"}},{"type":"image","attrs":{"src":"/journal/nos-idees-de-decoration-pour-vos-tables-de-mariage/5.jpg","width":2400,"height":1600,"alt":"Photos souvenirs accrochées à une ficelle"}},{"type":"image","attrs":{"src":"/journal/nos-idees-de-decoration-pour-vos-tables-de-mariage/6.jpg","width":997,"height":713,"alt":"Longue table noire décorée de bougies et de fleurs sombres"}},{"type":"paragraph","content":[{"type":"text","text":"N’hésitez pas à mélanger les couleurs et les styles : blanc et bois ou encore noir et végétal ! Peu importe la couleur ou le style de décoration que vous allez choisir, cela doit vous ressembler ! Pensez à vous et à ce que vous aimez et votre décoration sera forcément réussie et appréciée par vos convives. Spice Events vous "},{"type":"text","text":"accompagnera","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" à chaque étape de votre grand jour."}]}]}'::jsonb
) on conflict do nothing;

-- organiser-son-mariage-mode-d-emploi
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'a577dd85-553c-5c44-afa7-70767e83a543', 'publie', '2021-10-20T12:00:00+02:00'::timestamptz, 'organiser-son-mariage-mode-d-emploi',
  'Organiser son mariage : mode d''emploi',
  'Le seul mode d''emploi que vous aurez envie de lire',
  'Avant de se lancer dans cette grande aventure qu’est le mariage, il faut avoir quelques petites bases pour comprendre ce que fera votre wedding planner et vos…',
  'Conseils mariage', '2021-10-20'::date,
  '/journal/organiser-son-mariage-mode-d-emploi/couverture.jpg',
  'Mariés enlacés sous un voile',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Avant de se lancer dans cette grande aventure qu’est le mariage, il faut avoir quelques petites bases pour comprendre ce que fera votre wedding planner et vos prestataires techniques. Fini les modes d’emploi à s’en arracher les cheveux, Spice Events vous vient en "},{"type":"text","text":"aide","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" pour avoir toutes les cordes à votre arc. Un manuel qui vous permettra de réaliser votre mariage clef en main."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le lieu de réception, pour bien commencer"}]},{"type":"paragraph","content":[{"type":"text","text":"Dans un château, sur la plage, dans un jardin ou même à l’hôtel, les possibilités de lieux de réception sont diverses et variées. Tout aussi charmants les uns que les autres, ces lieux d’exception viendront constituer le cadre idyllique de votre mariage. Élément clef de votre mariage, le lieu de réception a pour but de mettre en avant votre personnalité, votre thématique et offrir à vos invités une expérience immersive inoubliable."}]},{"type":"paragraph","content":[{"type":"text","text":"Fort de vingt années d’expérience dans le domaine du "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", nous pouvons vous conseiller de nombreux partenaires et lieux de réceptions qui ont su faire leurs preuves au cours des années."}]},{"type":"image","attrs":{"src":"/journal/organiser-son-mariage-mode-d-emploi/1.jpg","width":2400,"height":1600,"alt":"Mariés assis de dos dans un jardin"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La technique au coeur de votre mariage"}]},{"type":"paragraph","content":[{"type":"text","text":"Dixit le tonton qui installe lui-même ses enceintes descendues tout droit du grenier (et risque de faire péter les plombs de tout le domaine), il ne faut pas laisser de côté la "},{"type":"text","text":"technique événementielle","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":". Véritable chef d’orchestre d’un événement réussi, une technique de qualité viendra embellir vos discours, vous mettra en lumière pour votre première danse et permettra de créer des éclairages scéniques à couper le souffle."}]},{"type":"paragraph","content":[{"type":"text","text":"Une technique faite entièrement sur-mesure par nos équipes qualifiées qui sauront vous expliquer et vous conseiller sur les meilleures techniques à adopter."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Des scénographies d’exception"}]},{"type":"paragraph","content":[{"type":"text","text":"La scénographie c’est en quelque sorte le décor de votre événement. Elle englobe les accessoires, la décoration florale, l’éclairage scénique, le mobilier et la technique. Elle viendra donner le ton de votre mariage et mettra en valeur votre thématique choisie."}]},{"type":"paragraph","content":[{"type":"text","text":"Entre les photos que vous trouvez sur les réseaux sociaux ou les recommandations de votre entourage, il n''est pas toujours évident de choisir chaque élément de sa scénographie. Nos équipes viennent à votre rencontre pour débriefer avec vous et trouver la meilleure scénographie, adaptée à vos envies et vos personnalités."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Les animations pour dynamiser votre mariage"}]},{"type":"paragraph","content":[{"type":"text","text":"Les animations sont devenues des éléments incontournables. Alors qu’autrefois un seul "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" suffisait pour faire “tourner les serviettes”, aujourd’hui elles ont un rôle à part entière et les prestataires doivent sans cesse trouver de nouvelles idées. Pour accompagner l’ambiance de votre mariage, faire bouger les foules sur la piste de danse ou occuper vos invités entre le vin d’honneur et le début du repas, rien de tel qu’une animation faite entièrement sur-mesure rien que pour vous !"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice, nous étoffons chaque jour nos offres pour vous proposer des "},{"type":"text","text":"animations tendances","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":". "},{"type":"text","text":"Bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":", "},{"type":"text","text":"photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":", "},{"type":"text","text":"DJ d’exception","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":"... Découvrez toutes nos idées insolites."}]},{"type":"image","attrs":{"src":"/journal/organiser-son-mariage-mode-d-emploi/2.jpg","width":2400,"height":1600,"alt":"Mariée posant près d''une voiture décapotable ancienne dans la brume"}},{"type":"paragraph","content":[{"type":"text","text":"Nous espérons que cet article vous aura aidé !"}]},{"type":"paragraph","content":[{"type":"text","text":"N’hésitez pas à nous contacter pour en savoir plus sur l’organisation de votre","marks":[{"type":"link","attrs":{"href":"/contact"}},{"type":"bold"}]},{"type":"text","text":" ","marks":[{"type":"bold"}]},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}},{"type":"bold"}]},{"type":"text","text":"."}]}]}'::jsonb
) on conflict do nothing;

-- osez-la-thematique-noire-pour-votre-mariage
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '0a721f06-3891-5ccb-aaa4-41873df59cde', 'publie', '2022-03-15T12:00:00+01:00'::timestamptz, 'osez-la-thematique-noire-pour-votre-mariage',
  'Osez la thématique noire pour votre mariage',
  'Et pourquoi pas ?',
  'De nos jours, les mariages se veulent originaux et modernes. Même si une majeure partie des futurs mariés préfèrent rester au blanc traditionnel, beaucoup…',
  'Conseils mariage', '2022-03-15'::date,
  '/journal/osez-la-thematique-noire-pour-votre-mariage/couverture.jpg',
  'Bouquet de fleurs sur fond noir',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"De nos jours, les mariages se veulent originaux et modernes. Même si une majeure partie des futurs mariés préfèrent rester au blanc traditionnel, beaucoup aimeraient se démarquer en utilisant une autre thématique. Spice a trouvé pour vous une thématique tendance et originale aussi classe et élégante que le blanc : le noir."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Se différencier"}]},{"type":"paragraph","content":[{"type":"text","text":"Aujourd’hui, presque toutes les décorations de mariage sont blanches. Synonyme de pureté et d''élégance, c’est la référence lorsqu''on parle de mariage. Mais il est temps de casser un peu les codes !"}]},{"type":"paragraph","content":[{"type":"text","text":"Si votre souhait est de vous démarquer des autres mariages, alors cette thématique est faite pour vous. Oubliez toutes les idées reçues sur le noir. Cette couleur qui n’en est pas vraiment une, a aussi ses qualités en matière de mariage !"}]},{"type":"image","attrs":{"src":"/journal/osez-la-thematique-noire-pour-votre-mariage/1.jpg","width":1000,"height":1000,"alt":"Table de mariage noire éclairée à la bougie"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Raffinée mais pas que !"}]},{"type":"paragraph","content":[{"type":"text","text":"Comme le blanc, le noir est très élégant et classe mais elle a aussi un côté mystérieux et chic."}]},{"type":"paragraph","content":[{"type":"text","text":"Contrairement à ce que l’on pourrait penser, ce n’est pas une couleur froide. Si elle est bien utilisée, elle peut être très chaleureuse. En l’associant avec des éléments bois et végétal, vous êtes sûrs d’apporter cette touche."}]},{"type":"image","attrs":{"src":"/journal/osez-la-thematique-noire-pour-votre-mariage/2.jpg","width":2400,"height":1600,"alt":"Mariée devant un décor de fleurs et d''ampoules suspendues"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Facile à associer"}]},{"type":"paragraph","content":[{"type":"text","text":"Le noir est également facile à associer. Comme le blanc, il a la particularité de se marier (sans mauvais jeu de mots) avec presque toutes les couleurs ! Vous avez donc l’embarras du choix en ce qui concerne son association."}]},{"type":"paragraph","content":[{"type":"text","text":"Toutefois, si vous souhaitez un maximum sur le total look noir, vous pouvez ajouter quelques touches de doré ou d’argenté pour rajouter de la lumière à votre décoration, sans tomber dans le too-much. Vous pouvez, par exemple, suspendre de "},{"type":"text","text":"jolies guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" pour rappeler ce deuxième choix de couleur."}]},{"type":"paragraph","content":[{"type":"text","text":"Vous êtes encore indécis et vous hésitez entre du blanc et du noir ? Et bien, sachez qu’une décoration au mélange de ces deux couleurs est également très jolie ! Alors conquis ?"}]},{"type":"image","attrs":{"src":"/journal/osez-la-thematique-noire-pour-votre-mariage/3.jpg","width":2400,"height":1478,"alt":"Mariés s''embrassant devant un rideau lumineux"}},{"type":"paragraph","content":[{"type":"text","text":"A vous de voir maintenant si cette thématique vous correspond !"}]},{"type":"paragraph","content":[{"type":"text","text":"Pour toutes questions, rendez-vous sur notre site internet."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-choisir-un-prestataire-technique-pour-son-mariage
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'f763037b-77a1-5a49-a299-79d4e4d492f6', 'publie', '2021-08-23T12:00:00+02:00'::timestamptz, 'pourquoi-choisir-un-prestataire-technique-pour-son-mariage',
  'Pourquoi choisir un prestataire technique pour son mariage ?',
  'Faites appel à des professionnels de l’événementiel',
  'Le choix d’un prestataire technique pour vos événements est essentiel au bon déroulement de votre journée et/ou week-end.',
  'Technique', '2021-08-23'::date,
  '/journal/pourquoi-choisir-un-prestataire-technique-pour-son-mariage/couverture.jpg',
  'Mariés front contre front dans une salle illuminée',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Le choix d’un "},{"type":"text","text":"prestataire technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" pour vos événements est essentiel au bon déroulement de votre journée et/ou week-end. Pour l’installation de votre scénographie, de l’éclairage et de la sonorisation, les équipes qualifiées sauront ajuster le matériel nécessaire en fonction du lieu et du type d’événement. Dixit le cousin qui tente de mettre l’éclairage et fait “cramer” les plombs du domaine ou votre meilleur ami - témoin qui dit “t’inquiète je gère”, notre équipe s’occupera de l’installation de A à Z et en toute sécurité. Un prestataire technique c’est donc important et on vous dit pourquoi."}]},{"type":"paragraph","content":[{"type":"text","text":"L’importance de la ","marks":[{"type":"bold"}]},{"type":"text","text":"technique événementielle","marks":[{"type":"link","attrs":{"href":"/a-propos"}},{"type":"bold"}]},{"type":"text","text":" : rien de mieux que des professionnels qui vous ","marks":[{"type":"bold"}]},{"type":"text","text":"conseillent.","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Quel éclairage sera le plus adapté à votre lieu, quelle sonorisation utiliser pour embellir vos discours, quelle scénographie mettre en place… Tous ces petits détails sont pensés en amont pour offrir à vous et vos invités une expérience immersive. Fini les prises de tête et les stress de l’organisation, chez Spice Events nous nous occupons de tout, de A à Z !"}]},{"type":"paragraph","content":[{"type":"text","text":"Nous organiserons en amont un entretien et une visite du lieu pour comprendre les différents besoins matériels, de l’enceinte à l''électricité. Eh oui, chaque élément a son importance et doit être minutieusement mis en place afin d’éviter tout problème de sécurité. ("},{"type":"text","text":"Allez voir notre page dédiée à l’accompagnement !","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" )"}]},{"type":"paragraph","content":[{"type":"text","text":"Nous établirons ensuite avec vous le devis ainsi qu’une feuille de route, c’est-à-dire, le déroulement de votre événement. Tout au long de notre aventure ensemble, nous resterons en contact et à votre disposition pour répondre à vos questions et vous informer sur l’avancée de l’"},{"type":"text","text":"organisation","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Choisir un prestataire technique c’est donc la garantie d’un événement réussi, de qualité et en toute sécurité.","marks":[{"type":"link","attrs":{"href":"/a-propos"}},{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Spice Events, créateur d’ambiance et d’expérience"}]},{"type":"paragraph","content":[{"type":"text","text":"Fort de vingt années d’expérience dans le domaine de l’événementiel, nous avons à cœur de vous offrir un événement d’exception, entièrement sur-mesure."}]},{"type":"paragraph","content":[{"type":"text","text":"Fini le DJ qui passe du Patrick Sébastien toute la soirée, chez Spice nous travaillons main dans la main avec des "},{"type":"text","text":"DJ passionnés","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" au style bien distinct. De la folk, au rock en passant par les variétés françaises, nous vous "},{"type":"text","text":"accompagnons","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" et vous mettons en relation avec le "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" qui conviendra le mieux à vos attentes."}]},{"type":"paragraph","content":[{"type":"text","text":"Vous souhaitez une scénographie digne d’un conte de fées ? Nous vous créons un éclairage scénique qui apportera une ambiance chaleureuse, romantique et magique. "},{"type":"text","text":"Guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":", rideaux étoilés ou mise en lumière de la façade, vos convives n’en reviendront pas !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Spice Events, c’est la garantie d’un événement sur-mesure qui vous fera voyager le temps de quelques instants"}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-engager-un-dj-professionnel-pour-votre-evenement
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'e644728f-7d97-593b-a41b-5a0f47c3b0e5', 'publie', '2021-11-09T12:00:00+01:00'::timestamptz, 'pourquoi-engager-un-dj-professionnel-pour-votre-evenement',
  'Pourquoi engager un DJ professionnel pour votre événement ?',
  'Spice Events vous dit tout.',
  'Vous hésitez encore à engager un DJ pour votre événement?',
  'Musique & ambiance', '2021-11-09'::date,
  '/journal/pourquoi-engager-un-dj-professionnel-pour-votre-evenement/couverture.jpg',
  'Contrôleur DJ et ordinateur portable',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vous hésitez encore à engager un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" pour votre événement?"}]},{"type":"paragraph","content":[{"type":"text","text":"Spice Events vous donne les raisons de confier votre ambiance musicale à un professionnel."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un gain de temps et de stress"}]},{"type":"paragraph","content":[{"type":"text","text":"Organiser et prévoir son "},{"type":"text","text":"animation","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" musicale prend du temps et nous savons que vous avez déjà beaucoup d’autres choses à vous occuper. Alors ne vous tracassez pas l’esprit avec une mission en plus et confiez cette tâche à un professionnel de la musique !"}]},{"type":"paragraph","content":[{"type":"text","text":"Elle sera entièrement réussie avec un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" professionnel. Vous avez juste à lui préciser ce que vous recherchez et le tour est joué."}]},{"type":"paragraph","content":[{"type":"text","text":"Plus de stress pour se décider sur la musique suivante, rejoignez vos convives sur la piste et décompressez. L’ambiance est lancée !"}]},{"type":"image","attrs":{"src":"/journal/pourquoi-engager-un-dj-professionnel-pour-votre-evenement/1.jpg","width":2400,"height":1600,"alt":"Public dansant sous des projecteurs rouges"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une adaptation à toute épreuve"}]},{"type":"paragraph","content":[{"type":"text","text":"Parce que c’est son métier, un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" saura faire le mixage idéal pour faire plaisir à toutes les personnes présentes et mélanger les différents styles."}]},{"type":"paragraph","content":[{"type":"text","text":"Qu’il y ait des fans de rock, rap, hip hop, électro ou encore de reggae, ce n’est pas un problème car votre "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" se débrouillera pour vous satisfaire !"}]},{"type":"paragraph","content":[{"type":"text","text":"Alors filez sur la piste et appréciez le moment !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un matériel de pro"}]},{"type":"paragraph","content":[{"type":"text","text":"En plus de disposer d’un bon matériel, un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" professionnel le connaît et saura créer l’ambiance que vous désirez. En avance, il pourra prévoir les enchaînements entre les musiques, les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":", les passages micros ou encore "},{"type":"text","text":"l’éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" en fonction de votre lieu de réception et des musiques. Nos "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" utilisent du matériel haut de gamme fourni par "},{"type":"text","text":"MX EVENEMENT","marks":[{"type":"link","attrs":{"href":"http://www.mxevenement.com"}}]},{"type":"text","text":"."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-engager-un-dj-professionnel-pour-votre-evenement/2.jpg","width":2400,"height":1600,"alt":"Platines et table de mixage éclairées"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une bonne image"}]},{"type":"paragraph","content":[{"type":"text","text":"Un problème de son, une fausse note technique, un micro qui ne fonctionne pas, etc. Ces incidents peuvent gâcher votre fête et c’est votre réputation qui est en jeu. Alors pour ne rien laisser au hasard, il est préférable de faire confiance à un professionnel."}]},{"type":"paragraph","content":[{"type":"text","text":"Engager un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" professionnel apportera de la crédibilité à votre événement et plus de sérieux surtout s’il s’agit d’un événement d’entreprise."}]},{"type":"paragraph","content":[{"type":"text","text":"Idem pour un événement privé, personne n’a envie d''assister à un cafouillage qui viendrait interrompre la fête."}]},{"type":"paragraph","content":[{"type":"text","text":"Au-delà de la technique, un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" sait s’adresser à un public et raviver son intérêt si besoin. Il agira comme le véritable garant de la bonne ambiance de votre événement."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-engager-un-dj-professionnel-pour-votre-evenement/3.jpg","width":2400,"height":1600,"alt":"Piste de danse sous des tubes lumineux bleus et roses"}},{"type":"paragraph","content":[{"type":"text","text":"Alors que ce soit pour votre mariage ou pour un anniversaire, vous savez maintenant pourquoi il est intéressant pour vous de faire confiance à un "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". Parce que peu importe ce qu’il y a à célébrer, un professionnel facilitera l’"},{"type":"text","text":"organisation","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" de votre événement et participera à sa réussite !"}]},{"type":"paragraph","content":[{"type":"text","text":"N’hésitez pas à nous contacter si vous avez des questions ou si vous souhaitez en savoir plus sur nos","marks":[{"type":"link","attrs":{"href":"/contact"}}]},{"type":"text","text":" "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" "},{"type":"text","text":"d’exception.","marks":[{"type":"link","attrs":{"href":"/contact"}}]}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-investir-dans-du-materiel-fiable-est-plus-responsable-pour
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '8c3be142-43aa-5f0d-9386-fc1abde126b2', 'publie', '2026-04-30T12:00:00+02:00'::timestamptz, 'pourquoi-investir-dans-du-materiel-fiable-est-plus-responsable-pour',
  'Pourquoi investir dans du matériel fiable est plus responsable pour l’environnement ?',
  'Une responsabilité qui dépasse la simple performance',
  'Dans l’événementiel, le choix du matériel est souvent guidé par des critères de performance et de rendu. Pourtant, il s’agit aussi d’un enjeu environnemental.',
  'Technique', '2026-04-30'::date,
  '/journal/pourquoi-investir-dans-du-materiel-fiable-est-plus-responsable-pour/couverture.jpg',
  'Atelier de matériel avec câbles enroulés et flight cases',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dans l’événementiel, le choix du matériel est souvent guidé par des critères de performance et de rendu. Pourtant, il s’agit aussi d’un enjeu environnemental. Investir dans un équipement fiable et durable ne répond pas uniquement à une exigence de qualité, mais participe également à une démarche plus responsable. Chez Spice Events, cette approche s’inscrit dans une vision globale : proposer des prestations maîtrisées tout en limitant leur impact sur le long terme."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-investir-dans-du-materiel-fiable-est-plus-responsable-pour/1.jpg","width":1365,"height":2048,"alt":"Structures en aluminium empilées en atelier"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La durabilité comme premier levier écologique"}]},{"type":"paragraph","content":[{"type":"text","text":"Un matériel fiable est conçu pour durer. Là où des équipements d’entrée de gamme nécessitent des remplacements fréquents, du matériel professionnel de qualité peut être utilisé pendant plusieurs années sans perte de performance. Cette longévité réduit directement la production de déchets électroniques, un enjeu majeur dans le secteur. Moins de remplacements signifie aussi moins de fabrication, donc une empreinte environnementale globale réduite."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Réduire la consommation liée au renouvellement"}]},{"type":"paragraph","content":[{"type":"text","text":"Chaque achat de matériel implique des ressources : matières premières, transport, production et distribution. En limitant la fréquence de renouvellement, on réduit mécaniquement cette chaîne de consommation. Investir dans un équipement fiable permet donc d’éviter une logique de surconsommation, souvent liée à des produits moins durables. C’est une approche plus raisonnée, qui privilégie la qualité à la quantité."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-investir-dans-du-materiel-fiable-est-plus-responsable-pour/2.jpg","width":2048,"height":1296,"alt":"Projecteurs rangés sur un portant"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une meilleure efficacité énergétique"}]},{"type":"paragraph","content":[{"type":"text","text":"Les équipements professionnels récents sont généralement conçus pour être plus efficaces énergétiquement. Éclairage LED, systèmes audio optimisés, gestion intelligente de la puissance : ces technologies permettent de réduire la consommation électrique sans compromettre la qualité du rendu. À l’échelle d’un événement, ces optimisations ont un impact direct sur l’empreinte énergétique."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Moins de pannes, moins de gaspillage"}]},{"type":"paragraph","content":[{"type":"text","text":"Un matériel fiable limite les risques de panne et les interventions d’urgence. Cela évite non seulement des interruptions de prestation, mais aussi des déplacements supplémentaires, du remplacement en urgence ou l’utilisation de matériel de secours non optimisé. Cette stabilité contribue à une gestion plus sobre et plus efficace des ressources."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-investir-dans-du-materiel-fiable-est-plus-responsable-pour/3.jpg","width":2048,"height":1365,"alt":"Tubes de structure rangés en atelier"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une logistique plus maîtrisée"}]},{"type":"paragraph","content":[{"type":"text","text":"Investir dans du matériel de qualité permet également de rationaliser la logistique. Des équipements fiables, bien entretenus et adaptés aux besoins réduisent les transports inutiles et les ajustements de dernière minute. Une organisation optimisée est souvent synonyme de réduction d’impact, notamment en limitant les allers-retours et les ajustements techniques imprévus."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une approche cohérente avec l’exigence de qualité"}]},{"type":"paragraph","content":[{"type":"text","text":"Responsabilité environnementale et exigence de qualité ne sont pas opposées, bien au contraire. Un matériel performant, durable et bien utilisé permet d’offrir une expérience plus fluide tout en s’inscrivant dans une démarche plus responsable. Chez Spice Events, cette cohérence est essentielle : chaque choix technique doit répondre à la fois à un niveau d’exigence élevé et à une logique de durabilité."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-investir-dans-du-materiel-fiable-est-plus-responsable-pour/4.jpg","width":1365,"height":2048,"alt":"Prise électrique et câbles de puissance"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Vers une vision plus responsable de l’événementiel"}]},{"type":"paragraph","content":[{"type":"text","text":"L’événementiel évolue vers des pratiques plus conscientes, où chaque décision compte. Le choix du matériel en fait partie. Privilégier des équipements fiables et durables est une manière concrète de réduire son impact tout en maintenant un haut niveau de prestation. C’est un engagement discret, mais essentiel, qui participe à la transformation du secteur."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"En conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Investir dans du matériel fiable, c’est faire le choix de la durabilité, de la performance et de la responsabilité. En limitant les remplacements, en réduisant la consommation et en optimisant l’utilisation des ressources, cette approche contribue à un événementiel plus respectueux de son environnement. Parce qu’au-delà de l’expérience vécue, la manière dont elle est produite a aussi toute son importance."}]},{"type":"paragraph","content":[{"type":"text","text":"Pour en savoir plus sur notre approche et nos prestations, rendez-vous sur "},{"type":"text","text":"www.spiceevents.fr","marks":[{"type":"link","attrs":{"href":"/"}}]},{"type":"text","text":"."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-l-accompagnement-en-amont-est-aussi-important-que-le-jour-j
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '34338753-b324-5656-ba20-6563c2e7097f', 'publie', '2026-03-18T12:00:00+01:00'::timestamptz, 'pourquoi-l-accompagnement-en-amont-est-aussi-important-que-le-jour-j',
  'Pourquoi l’accompagnement en amont est aussi important que le jour J ?',
  'Un accompagnement personnalisé pour votre grand jour !',
  'Lorsqu’on pense à un mariage réussi, l’attention se porte naturellement sur la soirée, la piste de danse ou l’ambiance le jour J.',
  'Conseils mariage', '2026-03-18'::date,
  '/journal/pourquoi-l-accompagnement-en-amont-est-aussi-important-que-le-jour-j/couverture.jpg',
  'Cérémonie laïque : une invitée lit un texte au micro devant les mariés',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lorsqu’on pense à un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" réussi, l’attention se porte naturellement sur la soirée, la piste de danse ou l’ambiance le jour J. Pourtant, l’expérience montre que la qualité d’un événement dépend en grande partie du "},{"type":"text","text":"travail réalisé en amont","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":". Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", chaque prestation repose sur une préparation structurée qui permet d’anticiper les attentes, d’éviter les imprévus et de garantir une exécution fluide le moment venu. Comme le souligne notre approche, un premier échange permet de découvrir précisément les envies des mariés afin de concevoir un événement réellement à leur image."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Comprendre le projet pour mieux le sublimer"}]},{"type":"paragraph","content":[{"type":"text","text":"L’"},{"type":"text","text":"accompagnement en amont","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" permet avant tout de comprendre la vision des mariés dans sa globalité. À travers des échanges personnalisés et un questionnaire détaillé, il devient possible de cerner les goûts musicaux, les moments clés et "},{"type":"text","text":"l’ambiance recherchée","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". Cette phase est essentielle car elle conditionne toutes les décisions suivantes : "},{"type":"text","text":"choix musicaux, rythme de la soirée","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", "},{"type":"text","text":"mise en lumière","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" ou encore coordination avec les autres prestataires. Sans ce travail préparatoire, l’exécution le jour J risque d’être plus standardisée et moins alignée avec les attentes réelles du couple."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-l-accompagnement-en-amont-est-aussi-important-que-le-jour-j/1.jpg","width":2400,"height":1600,"alt":"Mariés dansant sur une piste en parquet"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Anticiper pour sécuriser le déroulé"}]},{"type":"paragraph","content":[{"type":"text","text":"Un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" est une mécanique précise où chaque moment s’enchaîne. L’"},{"type":"text","text":"accompagnement en amont","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" permet de construire une véritable feuille de route de l’événement, en identifiant les temps forts et les points de vigilance. Cette planification détaillée, associée à une coordination avec l’ensemble des prestataires, garantit un déroulé fluide et ponctuel. L’objectif est clair : permettre aux mariés de vivre chaque instant avec sérénité, sans avoir à gérer la technique ou le timing pendant leur journée."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Créer une expérience réellement sur mesure"}]},{"type":"paragraph","content":[{"type":"text","text":"Contrairement à une approche standardisée, le travail préparatoire permet d’adapter finement chaque prestation. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"le mix musical, les transitions","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", "},{"type":"text","text":"l’éclairage","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" et les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" sont pensés en fonction du lieu, du public et du style souhaité. Cette personnalisation en profondeur est ce qui transforme une simple animation en véritable expérience. Elle repose sur une écoute active et sur des ajustements progressifs tout au long de la préparation."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-l-accompagnement-en-amont-est-aussi-important-que-le-jour-j/2.jpg","width":2400,"height":1600,"alt":"Mariés dansant sous des guirlandes lumineuses, en noir et blanc"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Réduire le stress des mariés"}]},{"type":"paragraph","content":[{"type":"text","text":"L’un des bénéfices majeurs de l’"},{"type":"text","text":"accompagnement en amont","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" est la tranquillité d’esprit qu’il apporte aux futurs mariés. En étant guidés étape par étape, ils peuvent se concentrer sur les autres aspects de leur organisation. Les retours clients montrent d’ailleurs que des échanges réactifs et structurés avant l’événement permettent aux couples d’aborder leur "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" avec beaucoup plus de sérénité. Cette dimension humaine fait pleinement partie de l’ADN de "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", où l’écoute et la proximité sont considérées comme essentielles à la réussite d’un événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une exécution le jour J rendue plus fluide"}]},{"type":"paragraph","content":[{"type":"text","text":"Lorsque la "},{"type":"text","text":"préparation","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" a été menée avec rigueur, le jour J devient l’aboutissement naturel du travail réalisé. L’installation est anticipée, les "},{"type":"text","text":"tests techniques","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" sont effectués et l’équipe peut se concentrer sur l’essentiel : l’"},{"type":"text","text":"énergie de la salle","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" et la "},{"type":"text","text":"qualité de l’ambiance","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":". Cette maîtrise en amont permet une exécution plus sereine, plus réactive et plus qualitative. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", chaque prestation est ainsi pensée pour allier préparation minutieuse et exécution sans faille."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-l-accompagnement-en-amont-est-aussi-important-que-le-jour-j/3.jpg","width":2048,"height":1365,"alt":"Alliances posées sur un livre ouvert"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’approche Spice Events : accompagner de A à Z"}]},{"type":"paragraph","content":[{"type":"text","text":"La philosophie de "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" repose sur une conviction simple : une grande soirée ne s’improvise pas. C’est pourquoi nous privilégions un "},{"type":"text","text":"accompagnement complet","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":", depuis les premiers échanges jusqu’à la dernière danse. Cette méthode permet de créer une expérience cohérente, fluide et fidèle aux attentes des mariés. Elle garantit également une meilleure "},{"type":"text","text":"coordination technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" et artistique, au service d’un seul objectif : faire vivre aux couples et à leurs invités un moment réellement mémorable."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"En conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"L’exécution le jour J est évidemment essentielle, mais elle n’est que la partie visible d’un travail beaucoup plus large. C’est l’"},{"type":"text","text":"accompagnement en amont","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":" qui sécurise l’événement, affine la personnalisation et permet d’atteindre un véritable niveau d’excellence. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", nous considérons cette phase préparatoire comme la clé d’une soirée réussie, parce que les plus beaux moments sont toujours ceux qui ont été parfaitement anticipés."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-la-coherence-visuelle-a-son-importance
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '899cd832-aff8-57ef-a5cd-7beb0392f59d', 'publie', '2026-04-30T12:00:00+02:00'::timestamptz, 'pourquoi-la-coherence-visuelle-a-son-importance',
  'Pourquoi la cohérence visuelle a son importance ?',
  'Un aspect qui fera toute la différence',
  'Avant même que la musique ne démarre ou que la soirée ne prenne son rythme, vos invités perçoivent d’abord une ambiance visuelle.',
  'Technique', '2026-04-30'::date,
  '/journal/pourquoi-la-coherence-visuelle-a-son-importance/couverture.jpg',
  'Dîner de gala sous des faisceaux de lumière bleue',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Avant même que la musique ne démarre ou que la soirée ne prenne son rythme, vos invités perçoivent d’abord une ambiance visuelle. Le regard capte l’éclairage, l’harmonie des couleurs, l’intégration du matériel et l’atmosphère générale du lieu. Cette première impression conditionne immédiatement la perception globale de l’événement. Une cohérence visuelle soignée installe une sensation de professionnalisme et d’élégance dès les premières minutes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une ambiance qui renforce l’expérience globale"}]},{"type":"paragraph","content":[{"type":"text","text":"La cohérence visuelle ne relève pas uniquement de l’esthétique. Elle participe directement à l’expérience vécue par les invités. Lorsque la lumière, la scénographie et l’environnement technique sont alignés avec le style du mariage ou de l’événement, l’immersion est plus forte et plus naturelle. À l’inverse, des éléments visuels disparates ou mal intégrés peuvent créer une rupture perceptible, même si la prestation musicale est de qualité. L’objectif est que chaque composante visuelle soutienne l’ambiance plutôt que de la perturber."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-coherence-visuelle-a-son-importance/1.jpg","width":1118,"height":738,"alt":"Salle de réception aux murs de briques mise en lumière"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’importance de l’intégration technique"}]},{"type":"paragraph","content":[{"type":"text","text":"Une cohérence visuelle réussie passe aussi par la discrétion et la qualité d’intégration du matériel. Le positionnement des éclairages, la gestion des câbles, la propreté des installations et le choix des effets lumineux contribuent à l’image globale de la soirée. Chez Spice Events, la technique n’est jamais pensée de manière isolée : elle est intégrée au décor et au lieu pour rester élégante tout en étant performante. Cette exigence participe fortement à la perception haut de gamme d’un événement (voir article : "},{"type":"text","text":"Pourquoi la technique est invisible quand elle est bien faite ?","marks":[{"type":"link","attrs":{"href":"/journal/pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite"}}]},{"type":"text","text":")."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une narration visuelle tout au long de la soirée"}]},{"type":"paragraph","content":[{"type":"text","text":"Une soirée réussie évolue dans le temps, et la cohérence visuelle doit suivre cette progression. L’ambiance lumineuse du cocktail, celle du dîner et celle de la soirée dansante ne répondent pas aux mêmes objectifs. Une mise en lumière bien pensée accompagne ces transitions et crée une véritable narration visuelle. Cette évolution subtile permet de maintenir l’attention des invités et de renforcer les temps forts sans rupture brutale."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-coherence-visuelle-a-son-importance/2.jpg","width":2400,"height":1350,"alt":"Salle de dîner éclairée en bleu et violet"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Valoriser le lieu et les moments clés"}]},{"type":"paragraph","content":[{"type":"text","text":"Chaque lieu de réception possède ses propres atouts architecturaux et son identité. Une approche visuelle cohérente permet de les mettre en valeur plutôt que de les masquer. L’éclairage peut souligner un volume, réchauffer une salle ou dynamiser une piste de danse. Il joue également un rôle clé lors des moments importants comme l’entrée des mariés, l’ouverture de bal ou certaines animations. Lorsqu’elle est bien maîtrisée, la lumière devient un véritable outil de mise en scène."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une signature professionnelle perceptible"}]},{"type":"paragraph","content":[{"type":"text","text":"Même si les invités ne l’analysent pas consciemment, la cohérence visuelle est immédiatement ressentie. Elle contribue à cette impression souvent exprimée après coup : “tout était propre, beau et fluide”. Cette perception est un marqueur fort de professionnalisme. Elle renforce la crédibilité du prestataire et participe à la mémorisation positive de l’événement."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-coherence-visuelle-a-son-importance/3.jpg","width":768,"height":1024,"alt":"Salle de réception éclairée en violet avec tables dressées"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’approche Spice Events"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice Events, chaque projet fait l’objet d’une réflexion visuelle globale. Le choix des éclairages, leur implantation, leur intensité et leur évolution sont pensés en cohérence avec le lieu, le format de l’événement et les attentes des clients. Cette approche permet de créer des ambiances élégantes, immersives et parfaitement maîtrisées, sans jamais tomber dans la surcharge."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une cohérence qui fait la différence"}]},{"type":"paragraph","content":[{"type":"text","text":"La cohérence visuelle est souvent invisible lorsqu’elle est réussie, mais son absence se remarque immédiatement. Elle contribue à la qualité perçue de l’événement, à l’immersion des invités et à la force des souvenirs laissés. Pour un mariage ou une soirée professionnelle, c’est un levier essentiel pour passer d’une simple prestation technique à une véritable expérience."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-la-qualite-du-materiel-de-sonorisation-change-toute-l-experience-de
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '4e34fe44-e0ff-5485-9dc4-8bd125f96081', 'publie', '2025-12-29T12:00:00+01:00'::timestamptz, 'pourquoi-la-qualite-du-materiel-de-sonorisation-change-toute-l-experience-de',
  'Pourquoi la qualité du matériel de sonorisation change toute l’expérience de votre événement ?',
  'Derrière une ambiance réussie se cache toujours un son parfaitement maîtrisé.',
  'Lors d’un mariage ou d’un événement, le son est un élément central… et pourtant, lorsqu’il est parfaitement maîtrisé, il se fait oublier.',
  'Technique', '2025-12-29'::date,
  '/journal/pourquoi-la-qualite-du-materiel-de-sonorisation-change-toute-l-experience-de/couverture.jpg',
  'DJ aux platines sous un projecteur',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lors d’un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou d’un "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", le son est un élément central… et pourtant, lorsqu’il est parfaitement maîtrisé, il se fait oublier. Une "},{"type":"text","text":"sonorisation de qualité","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" ne se remarque pas : elle se ressent. Elle accompagne les émotions, soutient les temps forts et garantit une expérience fluide pour tous les invités. À l’inverse, un matériel inadapté peut rapidement nuire à l’ambiance, même avec la meilleure programmation musicale."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un son clair, homogène et confortable pour tous"}]},{"type":"paragraph","content":[{"type":"text","text":"La qualité du matériel de sonorisation est essentielle pour assurer une écoute agréable et intelligible. Discours, cérémonie laïque, interventions parlées ou musique : chaque mot et chaque note doivent être audibles, sans saturation ni déséquilibre sonore. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", nous accordons une importance particulière à l’"},{"type":"text","text":"exigence technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", en nous appuyant notamment sur le matériel professionnel de "},{"type":"text","text":"MX ÉVÈNEMENT","marks":[{"type":"link","attrs":{"href":"https://mxevenement.com/"}},{"type":"bold"}]},{"type":"text","text":",","marks":[{"type":"bold"}]},{"type":"text","text":" reconnu pour la fiabilité et la "},{"type":"text","text":"performance de ses équipements","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":"."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-qualite-du-materiel-de-sonorisation-change-toute-l-experience-de/1.jpg","width":1170,"height":1147,"alt":"Console de mixage son"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La musique respectée, jamais déformée"}]},{"type":"paragraph","content":[{"type":"text","text":"Un bon système de sonorisation ne se contente pas de “faire du volume”. Il respecte la musique. Les basses sont maîtrisées, les médiums chaleureux et les aigus précis, sans agressivité. Cette fidélité sonore est indispensable pour créer une ambiance élégante, moderne et intergénérationnelle."}]},{"type":"paragraph","content":[{"type":"text","text":"Nous travaillons avec des équipements issus de marques de référence telles que L-Acoustics, Yamaha, Shure et bien d’autres, utilisés et maintenus dans les standards professionnels de "},{"type":"text","text":"MX ÉVÈNEMENT","marks":[{"type":"link","attrs":{"href":"https://mxevenement.com/"}},{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une sonorisation pensée pour chaque lieu"}]},{"type":"paragraph","content":[{"type":"text","text":"Chaque espace possède ses spécificités acoustiques : volumes, matériaux, hauteur sous plafond, réverbération… Une sonorisation réussie repose autant sur le matériel que sur son implantation et ses réglages. Grâce à une approche sur mesure et à des équipements adaptés, "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", en collaboration avec "},{"type":"text","text":"MX ÉVÈNEMENT","marks":[{"type":"link","attrs":{"href":"https://mxevenement.com/"}},{"type":"bold"}]},{"type":"text","text":",","marks":[{"type":"bold"}]},{"type":"text","text":" ajuste chaque installation pour garantir un rendu équilibré et confortable, quel que soit le lieu de réception."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-qualite-du-materiel-de-sonorisation-change-toute-l-experience-de/2.jpg","width":2048,"height":1365,"alt":"Platine DJ éclairée en rouge"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fiabilité technique et sérénité le jour J"}]},{"type":"paragraph","content":[{"type":"text","text":"Un équipement professionnel, entretenu et testé, est un gage de fiabilité. Moins de risques de coupures, de larsen* (*déf : oscillations parasites qui se manifestent par un sifflement, dans la diffusion du son par haut-parleurs) ou de pannes imprévues. Et lorsque chaque détail technique est anticipé, vous profitez pleinement de votre événement. Chaque prestation est préparée avec rigueur, avec des solutions de secours prévues et un matériel éprouvé, tel qu’utilisé par "},{"type":"text","text":"MX ÉVÈNEMENT","marks":[{"type":"link","attrs":{"href":"https://mxevenement.com/"}},{"type":"bold"}]},{"type":"text","text":" sur des événements de grande envergure."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La technique au service de l’émotion"}]},{"type":"paragraph","content":[{"type":"text","text":"La sonorisation doit soutenir l’émotion, jamais la voler. Lorsqu’elle est de qualité, elle s’efface pour laisser place aux instants forts : un discours émouvant, une musique partagée, une piste de danse qui se remplit naturellement. C’est cette vision que défend "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":" : une "},{"type":"text","text":"technique exigeante","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", discrète et fiable, inspirée des standards professionnels de "},{"type":"text","text":"MX ÉVÈNEMENT","marks":[{"type":"link","attrs":{"href":"https://mxevenement.com/"}},{"type":"bold"}]},{"type":"text","text":", pour faire vivre une expérience sonore fluide, élégante et mémorable."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '9c367427-bd0c-5f7a-8e62-f7765937f225', 'publie', '2025-12-23T12:00:00+01:00'::timestamptz, 'pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite',
  'Pourquoi la technique est invisible quand elle est bien faite ?',
  'Quand la technique se fond naturellement dans l''émotion de votre événement',
  'Lors d’un mariage ou d’un événement, les invités se souviennent d’une ambiance, d’une émotion, d’un moment fort.',
  'Technique', '2025-12-23'::date,
  '/journal/pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite/couverture.jpg',
  'Câbles branchés à l''arrière d''un équipement audio',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lors d’un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou d’un "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", les invités se souviennent d’une ambiance, d’une émotion, d’un moment fort. Rarement des câbles, des enceintes ou des projecteurs. Et c’est précisément là que réside la réussite d’une "},{"type":"text","text":"prestation technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" : quand elle disparaît au profit de l’expérience."}]},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice Events, nous sommes convaincus que la meilleure "},{"type":"text","text":"technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" est celle que l’on ne remarque pas… mais que l’on ressent."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une technique pensée pour l’expérience, pas pour être vue"}]},{"type":"paragraph","content":[{"type":"text","text":"Sonorisation, éclairage, vidéo, effets visuels : ces éléments sont essentiels, mais ne doivent jamais voler la vedette à votre "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":". Une installation réussie s’intègre naturellement au lieu, respecte son architecture et sublime l’instant sans jamais l’alourdir."}]},{"type":"paragraph","content":[{"type":"text","text":"Un son clair sans effet de saturation, une lumière qui met en valeur sans éblouir, des effets maîtrisés qui arrivent au bon moment : tout est une question d’équilibre et de précision."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite/1.jpg","width":1170,"height":1145,"alt":"Structures et projecteurs d''éclairage scénique en action"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Anticiper pour éviter l’improvisation"}]},{"type":"paragraph","content":[{"type":"text","text":"Si la "},{"type":"text","text":"technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" est invisible le jour J, c’est parce que tout a été pensé en amont. Repérage des lieux, étude des volumes, choix du matériel, scénarisation des temps forts… chaque détail est anticipé pour que rien ne perturbe le déroulé de votre "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Cette préparation permet d’éviter les ajustements visibles, les câbles mal placés ou les installations envahissantes. Résultat ? Une ambiance fluide, élégante et rassurante."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le bon matériel au bon endroit"}]},{"type":"paragraph","content":[{"type":"text","text":"La "},{"type":"text","text":"performance technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" ne dépend pas uniquement de la puissance du matériel, mais de son adéquation avec le lieu et le moment. Inutile d’en faire trop : mieux vaut un dispositif parfaitement dimensionné, réglé avec précision, qu’une démonstration technique inutile."}]},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice Events, nous sélectionnons chaque équipement pour sa fiabilité, sa discrétion et sa capacité à servir l’émotion, qu’il s’agisse d’une "},{"type":"text","text":"cérémonie laïque","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", d’un cocktail, d’une soirée dansante ou d’un "},{"type":"text","text":"événement professionnel","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":"."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite/2.jpg","width":1170,"height":1155,"alt":"Rayonnages de matériel dans un entrepôt"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Quand la technique devient un support à l’émotion"}]},{"type":"paragraph","content":[{"type":"text","text":"Une "},{"type":"text","text":"ouverture de bal spectaculaire","marks":[{"type":"link","attrs":{"href":"/animations/ouverture-de-bal"}}]},{"type":"text","text":", une prise de parole parfaitement audible, une lumière qui accompagne un moment clé… La "},{"type":"text","text":"technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" n’est jamais une fin en soi. Elle est là pour amplifier les émotions, renforcer l’impact d’un instant et créer des souvenirs durables."}]},{"type":"paragraph","content":[{"type":"text","text":"Lorsqu’elle est bien réalisée, les invités ne se demandent pas comment cela fonctionne. Ils profitent simplement du moment."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’accompagnement, clé d’une technique invisible"}]},{"type":"paragraph","content":[{"type":"text","text":"Enfin, une "},{"type":"text","text":"technique réussie","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" repose aussi sur "},{"type":"text","text":"l’accompagnement","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":". Conseiller, guider, rassurer, proposer les bonnes solutions sans surcharger : c’est ce qui permet de créer des "},{"type":"text","text":"événements","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":" cohérents, élégants et parfaitement maîtrisés."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-la-technique-est-invisible-quand-elle-est-bien-faite/3.jpg","width":2400,"height":1800,"alt":"Salle éclairée par des projecteurs et des lasers violets"}},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice Events, notre rôle est de transformer la "},{"type":"text","text":"technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" en une évidence, pour que vous n’ayez qu’une chose à faire : vivre pleinement votre "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":"."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-le-plan-b-meteo-doit-etre-pense-d-un-point-de-vue-technique
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '381e3b6e-524b-5490-a83f-29e3edb037c7', 'publie', '2026-04-30T12:00:00+02:00'::timestamptz, 'pourquoi-le-plan-b-meteo-doit-etre-pense-d-un-point-de-vue-technique',
  'Pourquoi le plan B météo doit être pensé d’un point de vue technique ?',
  'Tout ce qu''il faut anticiper pour un événement réussi',
  'Lorsqu’un mariage ou un événement comporte des moments en extérieur, la question de la météo est inévitable.',
  'Technique', '2026-04-30'::date,
  '/journal/pourquoi-le-plan-b-meteo-doit-etre-pense-d-un-point-de-vue-technique/couverture.jpg',
  'Mariés sous un parapluie sur une passerelle en bois',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lorsqu’un mariage ou un événement comporte des moments en extérieur, la question de la météo est inévitable. Pourtant, le plan B est encore trop souvent envisagé uniquement sous l’angle logistique ou esthétique. En réalité, il s’agit avant tout d’un sujet technique. Un repli mal anticipé peut impacter la qualité sonore, la mise en lumière, l’alimentation électrique ou encore la fluidité du déroulé. Chez Spice Events, l’anticipation technique fait partie intégrante de la préparation, car une ambiance réussie ne doit jamais dépendre d’un aléa météo."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La technique, pilier de la continuité de l’événement"}]},{"type":"paragraph","content":[{"type":"text","text":"Un événement repose sur un équilibre précis entre émotion et performance technique. C’est pourquoi chaque installation est calibrée, testée et optimisée pour garantir un rendu fiable et immersif, quelles que soient les contraintes du lieu. Lorsque la météo impose un changement de configuration, seule une préparation technique rigoureuse permet de maintenir ce niveau d’exigence. Sans cela, le risque est de dégrader l’expérience des invités au moment le plus important."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-le-plan-b-meteo-doit-etre-pense-d-un-point-de-vue-technique/1.jpg","width":1024,"height":1536,"alt":"Installation son et lumière en extérieur pour une réception"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Des contraintes techniques très concrètes"}]},{"type":"paragraph","content":[{"type":"text","text":"Passer d’un plan A extérieur à un plan B intérieur ne consiste pas simplement à déplacer du matériel. Les paramètres acoustiques changent, la diffusion sonore doit être recalibrée, et la mise en lumière doit être repensée en fonction du nouvel espace. Les besoins électriques peuvent également évoluer, tout comme les contraintes de câblage et de sécurité. Chez Spice Events, chaque prestation est conçue comme une véritable mise en scène technique où chaque réglage compte, ce qui permet d’absorber plus sereinement ce type d’imprévu."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’importance des tests et des redondances"}]},{"type":"paragraph","content":[{"type":"text","text":"Un plan B météo fiable repose sur la capacité à sécuriser l’installation. C’est pourquoi nos configurations intègrent des contrôles complets du matériel, des tests son et lumière ainsi que des systèmes de secours prêts à être activés si nécessaire. Cette logique de redondance est essentielle lorsque les conditions deviennent incertaines. Elle garantit la continuité de la prestation sans coupure ni dégradation perceptible pour les invités."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-le-plan-b-meteo-doit-etre-pense-d-un-point-de-vue-technique/2.jpg","width":645,"height":427,"alt":"Tente transparente dressée pour un dîner de mariage"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une coordination indispensable avec le lieu et les prestataires"}]},{"type":"paragraph","content":[{"type":"text","text":"Penser le plan B d’un point de vue technique implique également une communication étroite avec le lieu de réception et les autres intervenants. L’espace de repli doit être compatible avec la diffusion sonore, l’implantation lumière et les normes de sécurité. L’équipe technique doit pouvoir adapter rapidement la configuration sans perturber le timing global. Cette anticipation fait partie d’une approche professionnelle où rien n’est laissé au hasard."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Transformer un risque en simple ajustement"}]},{"type":"paragraph","content":[{"type":"text","text":"Lorsque le plan B est correctement pensé en amont, la météo cesse d’être une source de stress. Le basculement éventuel devient un simple ajustement opérationnel, invisible pour les invités. L’objectif n’est pas seulement de “sauver” la prestation, mais de maintenir le même niveau d’exigence et d’émotion quel que soit le scénario. C’est dans cette capacité d’adaptation maîtrisée que se mesure la solidité d’un dispositif technique."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’approche Spice Events"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice Events, la fiabilité repose sur un matériel professionnel haut de gamme, une préparation minutieuse et une exécution sans faille. Notre partenariat technique et nos procédures de vérification nous permettent d’anticiper les contraintes météo avec sérieux et méthode. Chaque événement est préparé avec l’idée qu’un imprévu peut survenir, afin que la qualité de l’expérience reste constante du premier au dernier moment."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-le-plan-b-meteo-doit-etre-pense-d-un-point-de-vue-technique/3.jpg","width":1000,"height":1000,"alt":"Enceinte installée pour une cérémonie en plein air"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Anticiper pour préserver l’expérience"}]},{"type":"paragraph","content":[{"type":"text","text":"Un plan B météo n’est pas une option de confort, mais une composante essentielle de la réussite technique d’un événement. Lorsqu’il est pensé correctement, il protège la fluidité, la qualité sonore et l’impact visuel de la soirée. Pour les mariés comme pour leurs invités, cela fait toute la différence entre une adaptation subie et une expérience parfaitement maîtrisée."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-les-moments-forts-ne-sont-pas-forcement-les-plus-bruyants
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'c724d80c-f4fe-5d2e-9b60-c826e904fd7f', 'publie', '2026-01-20T12:00:00+01:00'::timestamptz, 'pourquoi-les-moments-forts-ne-sont-pas-forcement-les-plus-bruyants',
  'Pourquoi les moments forts ne sont pas forcément les plus bruyants ?',
  'L''art du son expliqué',
  'On associe souvent, à tort, un moment fort à un pic sonore : musique puissante, volume élevé, effets spectaculaires.',
  'Musique & ambiance', '2026-01-20'::date,
  '/journal/pourquoi-les-moments-forts-ne-sont-pas-forcement-les-plus-bruyants/couverture.jpg',
  'Console de mixage son',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On associe souvent, à tort, un moment fort à un pic sonore : musique puissante, volume élevé, effets spectaculaires. Pourtant, dans un événement bien pensé — et particulièrement dans un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou un "},{"type":"text","text":"événement haut de gamme","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":" — les instants les plus marquants ne sont pas toujours ceux qui font le plus de bruit. Ce sont souvent ceux qui sont les mieux maîtrisés."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’émotion naît de la nuance, pas du volume"}]},{"type":"paragraph","content":[{"type":"text","text":"Un moment fort fonctionne avant tout parce qu’il crée une émotion sincère. Et cette émotion naît rarement dans la surenchère sonore. Une musique trop forte peut impressionner sur l’instant, mais elle laisse peu de place à la subtilité, à l’écoute et au ressenti. À l’inverse, un volume juste, une musique choisie avec précision ou une simple voix parfaitement audible peuvent toucher beaucoup plus profondément."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-les-moments-forts-ne-sont-pas-forcement-les-plus-bruyants/1.jpg","width":1200,"height":799,"alt":"Mains d''un DJ sur une table de mixage éclairée en bleu"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le contraste, clé de l’impact émotionnel"}]},{"type":"paragraph","content":[{"type":"text","text":"Un événement est un enchaînement de rythmes. Ce sont les contrastes qui donnent du relief : un silence après une musique, une montée progressive plutôt qu’un démarrage brutal, une pause avant un moment clé. Sans ces respirations, tout devient linéaire… et donc moins mémorable. Les moments forts marquent parce qu’ils arrivent au bon moment, pas parce qu’ils sont les plus bruyants."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le silence comme véritable outil technique"}]},{"type":"paragraph","content":[{"type":"text","text":"Le silence n’est jamais vide. Il est chargé de tension, d’attente, d’émotion. Bien utilisé, il capte l’attention de tous les invités. D''un point de vue "},{"type":"text","text":"technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", cela demande une grande précision : savoir couper un son au bon instant, laisser une phrase résonner, permettre à un regard, un geste ou une émotion de s’exprimer pleinement. Ce sont souvent ces instants-là que les invités retiennent."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-les-moments-forts-ne-sont-pas-forcement-les-plus-bruyants/2.jpg","width":2048,"height":1363,"alt":"Invités dansant devant la régie DJ éclairée en bleu"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trop de bruit fatigue, trop vite"}]},{"type":"paragraph","content":[{"type":"text","text":"Un volume sonore élevé sur la durée crée une fatigue auditive et émotionnelle. Les invités décrochent, discutent entre eux, se détachent du moment. À l’inverse, une "},{"type":"text","text":"sonorisation équilibrée","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" permet de maintenir l’attention, de respecter les temps calmes et de réserver la puissance sonore aux moments où elle a un véritable sens : la soirée dansante, un final, une surprise."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le rôle du DJ : bien plus que passer de la musique"}]},{"type":"paragraph","content":[{"type":"text","text":"Un bon DJ ne se contente pas d’enchaîner des morceaux. Il lit la salle, anticipe les réactions, comprend l’énergie du moment ("},{"type":"text","text":"voir article : ","marks":[{"type":"italic"}]},{"type":"text","text":"Comment un DJ lit-il une piste de danse ?","marks":[{"type":"link","attrs":{"href":"/journal/comment-un-dj-lit-il-une-piste-de-danse"}},{"type":"italic"}]},{"type":"text","text":"). Il sait quand accompagner discrètement et quand prendre le devant de la scène. Cette capacité à gérer les intensités, les silences et les transitions est ce qui transforme une simple playlist en véritable expérience."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-les-moments-forts-ne-sont-pas-forcement-les-plus-bruyants/3.jpg","width":2048,"height":1363,"alt":"Casque posé sur une table de mixage"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une mise en scène sonore au service de l’événement"}]},{"type":"paragraph","content":[{"type":"text","text":"La technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" est là pour servir le moment, pas pour le dominer. Une voix claire pendant une cérémonie, une musique douce lors d’un discours, une montée progressive pour une entrée ou une ouverture de bal… Chaque choix sonore participe à la narration globale de l’événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Des souvenirs plus forts, parce qu’ils sont mieux ressentis"}]},{"type":"paragraph","content":[{"type":"text","text":"Les invités se souviennent rarement du volume exact d’un moment. En revanche, ils se souviennent de ce qu’ils ont ressenti : un frisson, une larme, un sourire, un silence partagé. Ce sont ces émotions-là qui font la différence entre un événement réussi et un événement inoubliable. Chez Spice Events, nous pensons que la puissance d’un moment ne se mesure pas en décibels, mais en émotions. C’est en jouant sur la subtilité, la précision et le timing que nous créons des expériences sincères, élégantes et mémorables."}]}]}'::jsonb
) on conflict do nothing;

-- pourquoi-un-bon-dj-travaille-en-amont-avec-tous-les-prestataires-de-votre
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '64c4025d-b536-5206-a1b6-b9dbbeea92f3', 'publie', '2026-01-06T12:00:00+01:00'::timestamptz, 'pourquoi-un-bon-dj-travaille-en-amont-avec-tous-les-prestataires-de-votre',
  'Pourquoi un bon DJ travaille en amont avec tous les prestataires de votre événement ?',
  'Quand la coordination en coulisses fait toute la différence le jour J.',
  'Lorsqu’on pense au rôle d’un DJ, on imagine souvent la piste de danse, la musique et l’ambiance.',
  'Musique & ambiance', '2026-01-06'::date,
  '/journal/pourquoi-un-bon-dj-travaille-en-amont-avec-tous-les-prestataires-de-votre/couverture.jpg',
  'Invités dansant sous les projecteurs',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lorsqu’on pense au rôle d’un DJ, on imagine souvent la piste de danse, la musique et l’ambiance. Pourtant, derrière une soirée fluide et mémorable se cache un travail invisible mais essentiel : la coordination en amont avec l’ensemble des prestataires de l’événement. Un bon DJ ne se contente pas d’arriver le jour J avec ses platines. Il anticipe, échange et s’intègre à une équipe globale pour garantir une expérience sans fausse note."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le DJ, chef d’orchestre discret de votre événement"}]},{"type":"paragraph","content":[{"type":"text","text":"Dans un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou un événement privé, chaque prestataire joue une partition précise : traiteur, "},{"type":"text","text":"wedding planner","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", photographe, vidéaste, équipe technique, lieu de réception… Le DJ est souvent au cœur du timing. Il rythme la soirée, annonce les temps forts et assure les transitions. Pour que tout s’enchaîne naturellement, il doit connaître le déroulé exact de l’événement et s’aligner avec tous les intervenants. Cette coordination permet :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"d’éviter les temps morts,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"de synchroniser musique, lumière et animations,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"de respecter le rythme souhaité par les clients."}]}]}]},{"type":"image","attrs":{"src":"/journal/pourquoi-un-bon-dj-travaille-en-amont-avec-tous-les-prestataires-de-votre/1.jpg","width":736,"height":463,"alt":"Première danse des mariés dans la fumée lourde et les étincelles froides"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une collaboration essentielle avec le wedding planner ou le coordinateur"}]},{"type":"paragraph","content":[{"type":"text","text":"Lorsque l’événement est encadré par un "},{"type":"text","text":"wedding planner","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou un "},{"type":"text","text":"coordinateur","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", le DJ travaille main dans la main avec lui. En amont, ils échangent sur :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"le planning détaillé de la journée,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"les moments clés (entrée des mariés, discours, ouverture de bal, surprises),"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"les imprévus possibles et les plans B."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cette collaboration garantit une "},{"type":"text","text":"soirée fluide","marks":[{"type":"bold"}]},{"type":"text","text":", sans stress, où chaque temps fort arrive au bon moment."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Travailler avec le traiteur pour un timing parfait"}]},{"type":"paragraph","content":[{"type":"text","text":"Un bon DJ prend également contact avec le traiteur. Pourquoi ? Parce que le rythme musical doit s’adapter au service. Discours, animations ou moments forts ne doivent jamais perturber :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"l’envoi des plats,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"la fluidité du service,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"le confort des invités."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cette coordination permet d’assurer une ambiance cohérente, élégante et respectueuse du déroulé du repas."}]},{"type":"image","attrs":{"src":"/journal/pourquoi-un-bon-dj-travaille-en-amont-avec-tous-les-prestataires-de-votre/2.jpg","width":2048,"height":1365,"alt":"Salle voûtée en pierre éclairée par un rideau lumineux"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une entente clé avec les photographes et vidéastes"}]},{"type":"paragraph","content":[{"type":"text","text":"Certains instants ne se reproduisent qu’une seule fois. Un DJ professionnel échange avec les photographes et vidéastes pour :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"annoncer les temps forts à l’avance,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"leur laisser le temps de se positionner,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"éviter qu’un moment important ne soit manqué."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Résultat : des images réussies, capturant l’émotion au bon moment, sans improvisation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Anticiper les contraintes techniques avec le lieu et les prestataires"}]},{"type":"paragraph","content":[{"type":"text","text":"Chaque lieu a ses spécificités : acoustique, contraintes sonores, horaires, alimentation électrique."}]},{"type":"paragraph","content":[{"type":"text","text":"Un DJ expérimenté anticipe ces éléments en lien avec :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"le lieu de réception,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"les équipes techniques"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"les autres prestataires audiovisuels."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cette préparation permet :"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"d’adapter le matériel,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"d’optimiser la qualité sonore,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"d’éviter les mauvaises surprises le jour J."}]}]}]},{"type":"image","attrs":{"src":"/journal/pourquoi-un-bon-dj-travaille-en-amont-avec-tous-les-prestataires-de-votre/3.jpg","width":800,"height":800,"alt":"Salle de réception historique éclairée en rouge et violet"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une expérience plus sereine pour les clients"}]},{"type":"paragraph","content":[{"type":"text","text":"Pour les "},{"type":"text","text":"mariés","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou les "},{"type":"text","text":"organisateurs d’événements","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", cette coordination en amont est souvent invisible… et c’est justement le signe qu’elle est réussie. Ils peuvent profiter pleinement de leur événement, en toute confiance, sans avoir à gérer les détails techniques ou le timing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Chez Spice Events, une approche collective et sur-mesure"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez Spice Events, nous considérons le DJ comme un partenaire central de votre "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", intégré à une équipe globale. Chaque projet fait l’objet d’échanges en amont avec l’ensemble des prestataires afin de créer une expérience fluide, élégante et parfaitement maîtrisée. Parce qu’un "},{"type":"text","text":"événement réussi","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":" ne repose jamais sur une seule personne, mais sur une coordination invisible et efficace, au service de l’émotion et du plaisir des invités."}]}]}'::jsonb
) on conflict do nothing;

-- quelle-thematique-choisir-pour-son-mariage
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'f35f18ee-126a-5d7a-bab6-7f414479a384', 'publie', '2021-09-03T12:00:00+02:00'::timestamptz, 'quelle-thematique-choisir-pour-son-mariage',
  'Quelle thématique choisir pour son mariage ?',
  'Donnez le ton de votre mariage',
  'Le jour-J approche à grands pas, et vous n’avez toujours pas d’idée pour votre décoration. Vous jonglez d’idées en idées.',
  'Conseils mariage', '2021-09-03'::date,
  '/journal/quelle-thematique-choisir-pour-son-mariage/couverture.jpg',
  'Tables blanches décorées de lanternes en papier',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Le jour-J approche à grands pas, et vous n’avez toujours pas d’idée pour votre décoration. Vous jonglez d’idées en idées. Le champêtre vous séduit car vous avez vu 1000 photos sur Pinterest et votre tableau en est rempli, mais cette influenceuse a organisé un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" sobre et blanc et “c’est pas mal aussi”. Vous êtes tentés par une ambiance Disco, pour que tante Suzette danse elle aussi toute la nuit, mais bon… La moyenne est tout de même de trente ans. Pas de panique ! Notre équipe se charge de la décoration de votre "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" tout en mêlant professionnalisme et innovation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Thématique sur-mesure"}]},{"type":"image","attrs":{"src":"/journal/quelle-thematique-choisir-pour-son-mariage/1.jpg","width":2400,"height":1800,"alt":"Salle de réception lumineuse décorée de lanternes"}},{"type":"paragraph","content":[{"type":"text","text":"Créer la scénographie qui marquera les esprits est loin d’être chose facile. Il faut qu''elle se marie à la perfection au lieu de réception, corresponde à votre personnalité et soit spectaculaire. Chez Spice Events, nous avons élaboré quatre thématiques différentes à décliner à l’infini grâce à nos multiples options scénographiques."}]},{"type":"paragraph","content":[{"type":"text","text":"Thématique florale, blanche, noire ou encore bois, un large choix s’offre à vous. En effet, une scénographie de mariage ne tourne pas qu’autour des ronds de serviettes et des nappes, elle consiste à créer la magie de votre événement quel qu’il soit. Jeu de lumière, sonorisation, traiteur, décoration, fleurs… Un savant mélange qui offre à chaque détail une réelle valeur ajoutée."}]},{"type":"paragraph","content":[{"type":"text","text":"Chaque thématique sera donc unique, puisque chaque mariage l’est. Nous adapterons votre choix à la technique utilisée pour faire vivre chaque instant de votre mariage. Si des doutes persistent dans votre choix, nous mettons en place de nombreux entretiens et points téléphoniques afin de vous conseiller et vous orienter vers les meilleurs choix à adopter."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’éclairage scénique pour aller plus loin"}]},{"type":"image","attrs":{"src":"/journal/quelle-thematique-choisir-pour-son-mariage/2.jpg","width":1600,"height":2400,"alt":"Coin cosy en plein air avec tipi, tapis et bougies"}},{"type":"paragraph","content":[{"type":"text","text":"Nous l’avons vaguement abordé tout à l’heure, l’éclairage est intimement lié à la décoration et représente un élément essentiel pour la mise en valeur de votre événement. Pour votre cérémonie (religieuse ou non), votre première danse ou la mise en scène de votre lieu, ses déclinaisons sont infinies."}]},{"type":"paragraph","content":[{"type":"text","text":"Quand on parle d’"},{"type":"text","text":"éclairage scénique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", on ne parle pas de la simple lampe de bureau qui clignote lorsqu’une mouche vient se faufiler dedans, mais réellement d’une technique qui a pour but certes d’éclairer, mais également d''embellir votre événement. Lorsque vous voyez votre artiste préféré sur scène avec les lumières “qui bougent de partout”, c’est ça. Offrir un effet Waouw pour que vous vous en souveniez, même lorsque vous aurez 90 ans et que vous raconterez à vos petits enfants vos folles soirées de jeunesse."}]},{"type":"paragraph","content":[{"type":"text","text":"Étroitement lié à l’"},{"type":"text","text":"éclairage scénique","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":", pensez aussi à la mise en lumière de votre lieu : une façade ou un jardin révélés à la nuit tombée offrent un show lumineux spectaculaire. Couplé à une sonorisation sur-mesure comme de la musique ou une histoire contée (par vous ou un conteur professionnel), vous êtes sûrs de devenir les mariés de l’année !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Les thématiques du moment"}]},{"type":"paragraph","content":[{"type":"text","text":"Cet été, des thématiques ont séduit plus que d’autres. C’est le cas des mariages champêtres, bohème et chic."}]},{"type":"paragraph","content":[{"type":"text","text":"Mariage chic","marks":[{"type":"italic"}]},{"type":"text","text":" : on favorise une thématique blanche, sobre et élégante. Et pour accompagner cette thématique et la rendre encore plus belle on optera pour un rideau étoilé lumineux, la sonorisation du dîner ainsi que de la cérémonie et une mise en lumière du lieu. Accompagnez le tout d’un mobilier blanc et transparent avec quelques fleurs blanches pour finaliser le tout ; sans oublier le "},{"type":"text","text":"bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":" pour faire danser tous vos convives."}]},{"type":"paragraph","content":[{"type":"text","text":"Mariage champêtre","marks":[{"type":"italic"}]},{"type":"text","text":" : thématique florale, ambiance cocooning et chaleureuse ; voici les ingrédients d’un mariage champêtre réussi. Agrémenter avec des guirlandes champêtres, des compositions florales, des lettres géantes lumineuses et le tour y est !"}]},{"type":"image","attrs":{"src":"/journal/quelle-thematique-choisir-pour-son-mariage/3.jpg","width":1920,"height":1080,"alt":"Table de mariage champêtre sous des guirlandes en forêt"}},{"type":"paragraph","content":[{"type":"text","text":"Mariage bohème :","marks":[{"type":"italic"}]},{"type":"text","text":" On s’imagine déjà rien qu’en citant le nom ; une thématique bois, des tapis marocain au sol, des fleurs pampas partout, un chapiteau grandeur nature, "},{"type":"text","text":"un rideau étoilé lumineux","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":", un éclairage scénique aux tonalités chaudes et nous y voilà !"}]},{"type":"paragraph","content":[{"type":"text","text":"Vous hésitez entre telle et telle thématique ou n’avez simplement pas d’idée ? N’hésitez pas à","marks":[{"type":"bold"},{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"nous contacter","marks":[{"type":"link","attrs":{"href":"/contact"}},{"type":"bold"},{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"pour trouver ensemble la meilleure solution technique.","marks":[{"type":"bold"},{"type":"italic"}]}]}]}'::jsonb
) on conflict do nothing;

-- quelles-animations-tendances-a-organiser-pour-son-mariage
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'bed52885-3ccb-58f4-b2bd-99827698a2d8', 'publie', '2021-07-23T12:00:00+02:00'::timestamptz, 'quelles-animations-tendances-a-organiser-pour-son-mariage',
  'Quelles animations tendances à organiser pour son mariage ?',
  'Dynamiser votre soirée avec nos multiples animations tendances.',
  'Organiser un mariage ou un événement réussi repose sur une combinaison de plusieurs éléments : une ambiance soignée, une expérience immersive et des…',
  'Animations', '2021-07-23'::date,
  '/journal/quelles-animations-tendances-a-organiser-pour-son-mariage/couverture.jpg',
  'Invités dansant sous des lasers roses',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Organiser un mariage ou un événement réussi repose sur une combinaison de plusieurs éléments : une ambiance soignée, une expérience immersive et des animations qui marquent les esprits. Chez Spice Events, nous proposons des animations modernes, élégantes et interactives, pensées pour créer du lien entre vos invités et sublimer chaque moment de votre journée. Découvrez les animations les plus tendance pour mariage, soirée d’entreprise, anniversaire, ou tout autre événement."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Bar à vinyles : l’animation vintage idéale pour un mariage original"}]},{"type":"paragraph","content":[{"type":"text","text":"Le bar à vinyles est devenu une animation incontournable pour les mariages et événements à la recherche d’authenticité. Vos invités peuvent choisir, manipuler et jouer des disques parmi une sélection de vinyles soigneusement choisie. Cette animation interactive crée une ambiance conviviale et personnalisée, tout en apportant une touche rétro très appréciée. Idéale pour un mariage vintage, un cocktail animé ou un événement corporate, elle encourage la participation et fait naître des échanges spontanés entre les invités."}]},{"type":"image","attrs":{"src":"/journal/quelles-animations-tendances-a-organiser-pour-son-mariage/1.jpg","width":2400,"height":1600,"alt":"Mains qui fouillent un bac de vinyles"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Livre d’or audio : capturer les émotions autrement"}]},{"type":"paragraph","content":[{"type":"text","text":"Le livre d’or audio est une animation moderne qui séduit par son authenticité. À travers un combiné téléphonique rétro, vos invités laissent des messages vocaux spontanés, drôles, touchants ou émouvants."}]},{"type":"paragraph","content":[{"type":"text","text":"Cette animation crée des souvenirs audio uniques, parfaits pour revivre l’émotion du mariage ou de l’événement. Elle remplace avantageusement le livre d’or traditionnel et reste un choix très recherché pour les couples en quête d’une animation intime, innovante et pleine d’émotions."}]},{"type":"image","attrs":{"src":"/journal/quelles-animations-tendances-a-organiser-pour-son-mariage/2.jpg","width":736,"height":736,"alt":"Livre d''or audio : téléphone blanc et panneau « Audio Guestbook »"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Photobooth : l’incontournable des animations mariage et événement"}]},{"type":"paragraph","content":[{"type":"text","text":"Le Photobooth est une animation indémodable. Il permet à vos invités de repartir avec des photos instantanées et personnalisées, tout en créant des moments fun et spontanés. Personnalisable selon votre thème (cadres, arrière-plans, templates…), il s’intègre parfaitement à tous types d’événements : mariage, soirée privée, séminaire, inauguration, etc. C’est une valeur sûre pour dynamiser votre réception et créer une atmosphère chaleureuse."}]},{"type":"image","attrs":{"src":"/journal/quelles-animations-tendances-a-organiser-pour-son-mariage/3.jpg","width":564,"height":846,"alt":"Invité tenant un tirage du photobooth, en noir et blanc"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ouverture de bal spectaculaire : un moment fort sublimé par nos effets"}]},{"type":"paragraph","content":[{"type":"text","text":"L’ouverture de bal est l’un des temps forts d’un mariage. Chez Spice Events, nous la sublimons grâce à des effets scéniques maîtrisés : fumée lourde, étincelles froides, mise en lumière élégante et scénographie personnalisée. Ces effets rendent votre entrée magique, garantissent un rendu visuel spectaculaire et assurent une sécurité totale grâce à l’utilisation de matériel professionnel. Une solution parfaite pour les futurs mariés souhaitant marquer les esprits dès les premiers instants de la soirée."}]},{"type":"image","attrs":{"src":"/journal/quelles-animations-tendances-a-organiser-pour-son-mariage/4.jpg","width":736,"height":463,"alt":"Première danse des mariés dans la fumée lourde et les étincelles froides"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Guirlandes lumineuses : créer une ambiance chaleureuse et féerique"}]},{"type":"paragraph","content":[{"type":"text","text":"Les guirlandes lumineuses sont une solution simple et esthétique pour transformer un lieu. Elles apportent une atmosphère douce et romantique, idéale pour un repas extérieur, un plafond lumineux ou une mise en ambiance de salle. Très demandées dans les mariages bohèmes, nature, chic ou rustiques, elles permettent de créer un décor harmonieux tout en renforçant la cohérence visuelle de votre événement."}]},{"type":"image","attrs":{"src":"/journal/quelles-animations-tendances-a-organiser-pour-son-mariage/5.jpg","width":736,"height":1104,"alt":"Salle de réception décorée de rideaux lumineux et de lustres"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Murs élémentaires : murs d’eau & murs végétaux pour un décor unique"}]},{"type":"paragraph","content":[{"type":"text","text":"Les murs d’eau et murs végétaux proposés par Spice Events apportent une dimension décorative forte."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Le mur d’eau crée un mouvement fluide, élégant et hypnotique, parfait comme fond photo ou pour structurer un espace."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Le mur végétal ajoute un décor naturel, moderne et personnalisable avec néons, stickers, logos ou initiales."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ces installations sont idéales pour un photocall, une entrée de salle, un stand d’exposition, ou toute zone où l’on souhaite créer un impact visuel fort. Entièrement modulables, elles s’adaptent à tous les thèmes et toutes les configurations."}]},{"type":"image","attrs":{"src":"/journal/quelles-animations-tendances-a-organiser-pour-son-mariage/6.jpg","width":2400,"height":1800,"alt":"Mur végétal avec un logo d''entreprise"}},{"type":"paragraph","content":[{"type":"text","text":"Les animations jouent un rôle essentiel dans la réussite d’un mariage ou d’un événement. En choisissant des solutions modernes, élégantes et interactives, vous offrez à vos invités une expérience mémorable."}]},{"type":"paragraph","content":[{"type":"text","text":"Avec Spice Events, vous bénéficiez d’un "},{"type":"text","text":"accompagnement complet","marks":[{"type":"link","attrs":{"href":"/mariages#methode"}}]},{"type":"text","text":", "},{"type":"text","text":"d’animations tendances","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" et d’une "},{"type":"text","text":"expertise technique","marks":[{"type":"link","attrs":{"href":"/a-propos"}},{"type":"bold"}]},{"type":"text","text":" reconnue pour faire de votre événement un moment unique."}]}]}'::jsonb
) on conflict do nothing;

-- quels-sont-les-indispensables-pour-un-evenement-reussi
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '8dc0daff-ca17-52ac-aa85-264008cdf636', 'publie', '2021-07-21T12:00:00+02:00'::timestamptz, 'quels-sont-les-indispensables-pour-un-evenement-reussi',
  'Quels sont les indispensables pour un événement réussi ?',
  'Mariage, anniversaire, soirée d’entreprise, PACS… mode d’emploi d’un événement réussi',
  'Sonorisation, éclairage, DJ, décoration, animation...Tous ont un rôle essentiel à jouer pour rendre votre événement unique.',
  'Conseils mariage', '2021-07-21'::date,
  '/journal/quels-sont-les-indispensables-pour-un-evenement-reussi/couverture.jpg',
  'Invités tenant des cierges magiques',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sonorisation, éclairage, DJ, décoration, animation...Tous ont un rôle essentiel à jouer pour rendre votre événement unique. Permettant de dynamiser votre événement et de créer des souvenirs inoubliables, chez Spice, nous mettons tout en œuvre pour faire de cette soirée une réussite."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Bien choisir la technique de votre événement"}]},{"type":"paragraph","content":[{"type":"text","text":"La technique événementielle est un des éléments essentiels pour assurer le bon déroulement de votre événement."}]},{"type":"paragraph","content":[{"type":"text","text":"Une sonorisation de qualité et performante viendra mettre en valeur vos prises de parole, la musique ou vos animations. Fini les grésillements ou les discours inaudibles qui viendront gâcher votre événement ! Conscients de son importance, nous mettons un point d’honneur sur la qualité de notre matériel. L-Acoustics, YAMAHA, Pioneer… Nous sélectionnons les meilleures références et innovations dans le domaine de la sonorisation. Pour aller encore plus loin, nous choisissons du matériel design et performant tel que nos enceintes sur batterie MAUI5GO de LD Systems, parfaites pour se rendre invisibles dans votre décor."}]},{"type":"paragraph","content":[{"type":"text","text":"L’éclairage quant à lui, viendra mettre en lumière votre événement, votre première danse et le tant attendu “oui”. L’éclairage contribue à mettre en valeur chaque recoin de votre événement grâce à un éclairage scénique : gobo, guirlandes champêtres, rideaux étoilés… Ces éléments viendront créer l’univers que vous souhaitez offrir à vos invités pour leur offrir une expérience inédite."}]},{"type":"image","attrs":{"src":"/journal/quels-sont-les-indispensables-pour-un-evenement-reussi/1.jpg","width":1920,"height":1080,"alt":"Mariés front contre front dans une salle illuminée"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Bien choisir son DJ"}]},{"type":"paragraph","content":[{"type":"text","text":"Trouver le DJ qui correspond le mieux à ses attentes est parfois chose complexe. Il faut que ce dernier comprenne vos attentes et que vous compreniez son style musical. En effet, votre futur DJ sera celui sur qui, quasiment tout repose : l’animation du repas, la sonorisation de votre cérémonie laïque, l’ouverture de bal... Il a un rôle essentiel à jouer. C’est pourquoi, nous portons une attention toute particulière à ces moments clefs qui donneront le ton de votre événement, en travaillant main dans la main avec les meilleurs DJ."}]},{"type":"paragraph","content":[{"type":"text","text":"Fort de vingt ans d’expérience dans le monde de l’événementiel, nous vous accompagnons et mettons en relation avec l’un de nos "},{"type":"text","text":"DJ partenaires","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":". Des DJ professionnels et qualifiés, triés sur le volet par nos soins."}]},{"type":"paragraph","content":[{"type":"text","text":"Vous êtes plus house ? Rock ? Folk ? Variété ? Aucun souci, nous avons le DJ qu’il vous faut ! Notre questionnaire musical vous permettra de sélectionner et choisir l’ambiance dont vous rêvez. Un questionnaire qui a su faire ses preuves au fil des années et que nous ne cessons d’améliorer pour votre entière satisfaction."}]},{"type":"paragraph","content":[{"type":"text","text":"Une prestation entièrement personnalisée et sur-mesure pour que vous passiez un agréable moment."}]},{"type":"image","attrs":{"src":"/journal/quels-sont-les-indispensables-pour-un-evenement-reussi/2.jpg","width":2400,"height":1597,"alt":"DJ aux platines dans une lumière rose"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Bien choisir ses animations"}]},{"type":"paragraph","content":[{"type":"text","text":"Bar à Vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":", "},{"type":"text","text":"PhotoBooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":", "},{"type":"text","text":"Ouverture de bal spectaculaire","marks":[{"type":"link","attrs":{"href":"/animations/ouverture-de-bal"}}]},{"type":"text","text":"…. Chez Spice Events nous étoffons sans cesse nos offres pour vous proposer des animations événementielles exceptionnelles. Ces animations permettent de dynamiser votre événement et de “briser la glace” auprès des invités qui ne se connaissent pas forcément."}]},{"type":"paragraph","content":[{"type":"text","text":"Le bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":" : pour le cocktail, l''ouverture de bal, sonoriser votre cérémonie laïque ou animer toute la soirée sous le son des vinyles ; notre bar inédit vous accompagne toute la nuit pour faire la fête ! Ce concept musical consiste à faire participer vos convives en choisissant eux-mêmes l''artiste et la musique de leurs choix. Ils deviennent à leur tour le DJ de la soirée, aidés par notre DJ professionnel qui saura les conseiller et les orienter dans leur recherche."}]},{"type":"image","attrs":{"src":"/journal/quels-sont-les-indispensables-pour-un-evenement-reussi/3.jpg","width":2400,"height":1643,"alt":"Bacs de vinyles"}},{"type":"paragraph","content":[{"type":"text","text":"PhotoBooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":" : quoi de mieux qu''une photo pour se souvenir des moments passés ? Le PhotoBooth est une solution simple, pratique & fun. Le plus ? Cette machine vous imprimera en direct la photo pour repartir avec. Vous la voulez en format numérique ? Aucun souci, elle vous l''envoie sur votre adresse mail ! Avec ou sans mise en scène, il saura apporter une touche de fun à vos événements."}]},{"type":"paragraph","content":[{"type":"text","text":"Ouverture de bal spectaculaire","marks":[{"type":"link","attrs":{"href":"/animations/ouverture-de-bal"}}]},{"type":"text","text":" : Offrez-vous une ouverture de bal digne d’un véritable moment de cinéma grâce à la combinaison de la fumée lourde, qui crée un nuage doux et flottant sous vos pas, et des étincelles froides, qui s’illuminent autour de vous comme un décor féerique. Cette mise en scène raffinée transforme votre première danse en un instant magique, parfaitement sécurisé et orchestré avec précision. Une entrée en matière spectaculaire, romantique et inoubliable pour lancer votre soirée. Une animation qui saura faire danser vos convives ! "},{"type":"text","text":"Découvrez toutes nos autres animations en cliquant ici !","marks":[{"type":"link","attrs":{"href":"/animations"}},{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Bien choisir sa décoration"}]},{"type":"paragraph","content":[{"type":"text","text":"Thématique bois, végétal, blanche ou noire, éclairage scénique, animation décorative… Ces petits éléments donnent le ton de votre événement. Ils permettent de créer l’ambiance que vous souhaitez et d’offrir à vos invités une expérience inégalée. Agrémentez votre décoration à l’aide de notre éclairage scénique, nos guirlandes champêtres, étincelles froides ou nos rideaux étoilés & embellissez l’extérieur avec nos lettres géantes lumineuses faites sur-mesure pour chaque événement."}]},{"type":"image","attrs":{"src":"/journal/quels-sont-les-indispensables-pour-un-evenement-reussi/4.jpg","width":1920,"height":1080,"alt":"Mariés dansant entre des fontaines d''étincelles froides"}}]}'::jsonb
) on conflict do nothing;

-- s-offrir-un-mariage-100-responsable-et-soucieux-de-l-environnement
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '11b0c239-7c60-5ba2-b304-9659c2aa5b15', 'publie', '2021-08-24T12:00:00+02:00'::timestamptz, 's-offrir-un-mariage-100-responsable-et-soucieux-de-l-environnement',
  'S''offrir un mariage 100% responsable et soucieux de l''environnement',
  'Créer un mariage qui veut du bien à la planète',
  'Un mariage oui, mais responsable de l’environnement, c’est encore mieux.',
  'Conseils mariage', '2021-08-24'::date,
  '/journal/s-offrir-un-mariage-100-responsable-et-soucieux-de-l-environnement/couverture.jpg',
  'Mariés enlacés au milieu de la végétation',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Un mariage oui, mais responsable de l’environnement, c’est encore mieux. Soucieux de mettre l’écologie au cœur de notre profession, chez Spice Events, nous développons régulièrement nos offres pour vous offrir des événements encore plus époustouflants les uns que les autres."}]},{"type":"paragraph","content":[{"type":"text","text":"A l’heure où l’environnement devient un sujet de plus en plus préoccupant, nous cherchons sans cesse à nous renouveler tout en gardant la qualité de notre prestation : éclairage LED, traiteur favorisant le circuit-court…"}]},{"type":"paragraph","content":[{"type":"text","text":"On vous en dit un peu plus sur ces options green qui font du bien à la planète !","marks":[{"type":"italic"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"De l’animation à la technique, tout peut être responsable"}]},{"type":"paragraph","content":[{"type":"text","text":"Bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":", "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" recyclées, "},{"type":"text","text":"éclairage LED, sonorisation","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" moins énergivore… Nous mettons tout en œuvre pour réduire au maximum notre empreinte carbone."}]},{"type":"paragraph","content":[{"type":"text","text":"Le "},{"type":"text","text":"bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":", l’une de nos dernières animations mises en place durant le confinement est l’une des stratégies acoustiques pour réduire au maximum sa consommation. On recycle des vieux vinyles destinés à la poubelle pour les faire devenir l’acteur principal de votre soirée. Fouillez, piochez, donnez au "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" le vinyle que vous souhaitez écouter ; nostalgie et fun assurés ! Et parce que l’upcycling nous tient à cœur, nous créons nos lettres géantes lumineuses à base de palettes de bois."}]},{"type":"image","attrs":{"src":"/journal/s-offrir-un-mariage-100-responsable-et-soucieux-de-l-environnement/1.jpg","width":2400,"height":1600,"alt":"Vinyles classés par ordre alphabétique"}},{"type":"paragraph","content":[{"type":"text","text":"Au-delà de l’upcycling, nous cherchons à vous offrir une prestation de qualité en se dirigeant de préférence vers du matériel moins énergivore. Nous mettons à votre disposition un large éventail de possibilités pour faire de votre mariage un instant unique."}]},{"type":"image","attrs":{"src":"/journal/s-offrir-un-mariage-100-responsable-et-soucieux-de-l-environnement/2.jpg","width":2048,"height":1365,"alt":"Mariés s''embrassant dans un jardin"}},{"type":"paragraph","content":[{"type":"text","text":"N’hésitez pas à nous contacter pour en savoir plus sur l’aspect éco-responsable de nos événements.","marks":[{"type":"link","attrs":{"href":"/contact"}},{"type":"bold"}]}]}]}'::jsonb
) on conflict do nothing;

-- se-marier-en-hiver
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  '25d352ba-297d-51b5-a331-adeb7bbd7ed5', 'publie', '2022-01-13T12:00:00+01:00'::timestamptz, 'se-marier-en-hiver',
  'Se marier en hiver',
  'Tous les avantages d''un mariage hivernal',
  'Une tendance de plus en plus adoptée par les mariés, qui préfèrent se dire oui sous la neige plutôt qu''au soleil.',
  'Conseils mariage', '2022-01-13'::date,
  '/journal/se-marier-en-hiver/couverture.jpg',
  'Mariés s''embrassant sur un chemin enneigé',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Une tendance de plus en plus adoptée par les mariés, qui préfèrent se dire oui sous la neige plutôt qu''au soleil."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"De nombreux avantages"}]},{"type":"paragraph","content":[{"type":"text","text":"Choisir d’organiser son mariage en période hivernale comporte plusieurs avantages."}]},{"type":"paragraph","content":[{"type":"text","text":"Tout d’abord, les "},{"type":"text","text":"prestataires","marks":[{"type":"link","attrs":{"href":"/"}}]},{"type":"text","text":" sont plus disponibles puisqu’il y a moins d’événements prévus sur cette période. De ce fait, ils seront également plus attentifs et réactifs à vos demandes en raison de leur agenda plus léger. Certains seront même prêts à vous offrir des remises tandis que d’autres proposent déjà des tarifs plus avantageux sur ces dates. Autre personne plus disponible à cette période : vos invités. Contrairement à l’été, ils ne seront pas en vacances et pourront répondre présent à votre invitation !"}]},{"type":"paragraph","content":[{"type":"text","text":"La météo est un autre avantage au mariage hivernal. Vous n’aurez pas à craindre la pluie puisque votre réception se passe déjà à l’intérieur ! Le froid est aussi plus convivial. En effet, nous apprécions davantage être entouré lorsqu''il fait froid. Personne n’aime être enfermé avec des dizaines de personnes quand il fait chaud !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Un mariage plus original"}]},{"type":"paragraph","content":[{"type":"text","text":"Se marier l’hiver apporte aussi une touche d’originalité à votre événement."}]},{"type":"paragraph","content":[{"type":"text","text":"Les mariés pourront se différencier grâce à des matières hivernales telles que la laine ou la fourrure. La mariée, elle, osera la robe manches longues, les gants, l’écharpe en fourrure, les bottines ou encore les plumes. Et qui dit look original dit "},{"type":"text","text":"photo","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":" de mariage originale !"}]},{"type":"paragraph","content":[{"type":"text","text":"Un mariage en hiver permet aussi d’oser certains aliments ou repas. Une fondue au chocolat, aux fromages, du chocolat chaud, du vin chaud ou encore des guimauves ont tout à fait leur place à cette période de l’année !"}]},{"type":"paragraph","content":[{"type":"text","text":"Vous pouvez également ajouter des éléments comme des grosses bougies, des "},{"type":"text","text":"guirlandes","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" dorées, du bois, des plaids ou des décorations en forme de flocon. Le gros plus serait de disposer d’un lieu de réception avec cheminée."}]},{"type":"paragraph","content":[{"type":"text","text":"Enfin, le petit plus qui fera son grand effet si vous habitez dans des régions où la neige tombe régulièrement en hiver, serait qu’elle fasse son apparition ce jour-là !"}]},{"type":"paragraph","content":[{"type":"text","text":"Vous n’avez plus qu’à croiser les doigts !"}]},{"type":"image","attrs":{"src":"/journal/se-marier-en-hiver/1.jpg","width":2400,"height":1600,"alt":"Mariés riant sous la neige"}},{"type":"paragraph","content":[{"type":"text","text":"Vous connaissez à présent tous les avantages d''un mariage hivernal !"}]},{"type":"paragraph","content":[{"type":"text","text":"Toutefois si vous souhaitez d''autres renseignements, n''hésitez pas à nous contacter.","marks":[{"type":"link","attrs":{"href":"/contact"}}]},{"type":"text","text":" "},{"type":"text","text":"Vous pouvez également consulter notre site web si vous êtes en quête d''inspiration, d''animations et de thématiques !","marks":[{"type":"link","attrs":{"href":"/"}}]}]}]}'::jsonb
) on conflict do nothing;

-- trop-d-animations-le-piege
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'd4a2eb51-15b0-5e96-ab6e-8efc2bf3bca1', 'publie', '2026-04-01T12:00:00+02:00'::timestamptz, 'trop-d-animations-le-piege',
  'Trop d''animations : le piège',
  'Comment garder une expérience qualitative',
  'Lors de la préparation d’un mariage ou d’un événement, il est naturel de vouloir surprendre et divertir ses invités.',
  'Animations', '2026-04-01'::date,
  '/journal/trop-d-animations-le-piege/couverture.jpg',
  'Bac de vinyles feuilleté par une main',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lors de la préparation d’un "},{"type":"text","text":"mariage","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" ou d’un "},{"type":"text","text":"événement","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":", il est naturel de vouloir surprendre et divertir ses invités. "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":", "},{"type":"text","text":"bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":", "},{"type":"text","text":"livre d''or audio","marks":[{"type":"link","attrs":{"href":"/animations/livre-d-or-audio"}}]},{"type":"text","text":", "},{"type":"text","text":"guirlandes lumineuses","marks":[{"type":"link","attrs":{"href":"/animations/guirlandes-lumineuses"}}]},{"type":"text","text":" ou autres "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" : les possibilités sont nombreuses et séduisantes. Pourtant, multiplier les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" sans véritable stratégie peut produire l’effet inverse de celui recherché. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", nous observons régulièrement qu’un excès d’"},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" nuit à la fluidité et à l’impact global de la soirée."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’animation doit servir l’expérience, pas la surcharger"}]},{"type":"paragraph","content":[{"type":"text","text":"Les "},{"type":"text","text":"animations tendances","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" apportent une vraie valeur lorsqu’elles sont bien intégrées à la soirée et cohérentes avec l’ambiance souhaitée. L’objectif n’est pas d’occuper chaque minute, mais de créer des moments forts mémorables. Une accumulation d’activités peut fragmenter l’attention des invités, casser la dynamique de la piste de danse et diluer l’émotion. Comme le rappelle notre approche chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" doivent donner du style à l’événement et créer des souvenirs, pas saturer le programme."}]},{"type":"image","attrs":{"src":"/journal/trop-d-animations-le-piege/1.jpg","width":736,"height":736,"alt":"Téléphone rétro blanc du livre d''or audio"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le risque de casser la dynamique de la soirée"}]},{"type":"paragraph","content":[{"type":"text","text":"Une soirée réussie repose sur un rythme progressif. Lorsque les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" s’enchaînent trop vite ou sont trop nombreuses, la montée en puissance devient difficile à maintenir. Les invités passent d’une activité à une autre sans véritable temps d’immersion. Résultat : la piste de danse met plus de temps à se remplir ou se vide plus rapidement. La clé est de préserver des respirations naturelles et de laisser l’ambiance musicale faire son travail."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La qualité prime toujours sur la quantité"}]},{"type":"paragraph","content":[{"type":"text","text":"Une "},{"type":"text","text":"animation","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" bien choisie et parfaitement exécutée aura toujours plus d’impact que plusieurs "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" moyennes. Un "},{"type":"text","text":"photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":" bien placé ou un "},{"type":"text","text":"bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":" peuvent devenir de véritables points d’attractions et générer des souvenirs forts. À l’inverse, multiplier les dispositifs peut diluer l’attention et créer une impression de dispersion. L’enjeu est donc de sélectionner les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" en fonction du profil des invités, du lieu et du timing global."}]},{"type":"image","attrs":{"src":"/journal/trop-d-animations-le-piege/2.jpg","width":564,"height":564,"alt":"Invité tenant son tirage devant la borne photobooth, en noir et blanc"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Une question de cohérence et de timing"}]},{"type":"paragraph","content":[{"type":"text","text":"Toutes les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" ne sont pas adaptées à tous les moments de la journée. Certaines fonctionnent parfaitement pendant le "},{"type":"text","text":"cocktail","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", d’autres prennent tout leur sens en soirée. Sans une vision d’ensemble du déroulé, le risque est de créer des chevauchements ou des temps morts. Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", l’intégration des "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" se fait toujours en lien avec le planning global afin de préserver la fluidité de l’événement. Nous vous conseillons de prévoir vos "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" entre la fin du dîner et avant l''arrivée de la pièce montée. Choix stratégique ! Cela permet de ne pas engendrer du retard sur le service du traiteur et à vos invités de digérer un peu tout en s''amusant !"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’importance du regard professionnel"}]},{"type":"paragraph","content":[{"type":"text","text":"Parce qu’ils interviennent sur de nombreux événements, les professionnels de l’événementiel disposent d’un recul précieux sur ce qui fonctionne réellement en conditions réelles. Leur rôle est aussi de conseiller, parfois de tempérer certaines envies et d’orienter vers les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" les plus pertinentes. Cette phase de conseil permet d’éviter l’effet “catalogue” et de construire une soirée équilibrée."}]},{"type":"image","attrs":{"src":"/journal/trop-d-animations-le-piege/3.jpg","width":1623,"height":1080,"alt":"Première danse des mariés dans la fumée lourde éclairée en rose"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"L’approche Spice Events"}]},{"type":"paragraph","content":[{"type":"text","text":"Chez "},{"type":"text","text":"Spice Events","marks":[{"type":"bold"}]},{"type":"text","text":", les "},{"type":"text","text":"animations tendances","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" sont proposées comme des leviers d’ambiance ciblés et non comme une accumulation systématique. "},{"type":"text","text":"Photobooth","marks":[{"type":"link","attrs":{"href":"/animations/photobooth"}}]},{"type":"text","text":", "},{"type":"text","text":"bar à vinyles","marks":[{"type":"link","attrs":{"href":"/animations/bar-a-vinyles"}}]},{"type":"text","text":" ou autres concepts sont intégrés de manière réfléchie pour renforcer l’expérience sans nuire au rythme de la soirée. Chaque recommandation tient compte du lieu, du nombre d’invités, du style recherché et du déroulé global."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trouver le juste équilibre"}]},{"type":"paragraph","content":[{"type":"text","text":"Une soirée mémorable n’est pas celle qui propose le plus d’"},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":", mais celle qui maintient l’attention et l’énergie des invités du début à la fin. Le bon équilibre repose sur une sélection pertinente, un timing maîtrisé et une vision d’ensemble cohérente. Bien dosées, les "},{"type":"text","text":"animations","marks":[{"type":"link","attrs":{"href":"/animations"}}]},{"type":"text","text":" deviennent de véritables accélérateurs d’ambiance. Mal calibrées, elles peuvent au contraire fragmenter l’expérience."}]}]}'::jsonb
) on conflict do nothing;

-- une-ambiance-intergenerationnelle
insert into public.articles (id, statut, publie_le, slug, titre, sous_titre, description, categorie, date_publication, couverture, couverture_alt, contenu) values (
  'a87d29df-0662-541c-86cc-b785064040c4', 'publie', '2026-02-25T12:00:00+01:00'::timestamptz, 'une-ambiance-intergenerationnelle',
  'Une ambiance intergénérationnelle',
  'Faire danser toutes les générations, sans compromis',
  'Créer une ambiance intergénérationnelle est aujourd’hui l’un des plus grands défis de l’événementiel.',
  'Musique & ambiance', '2026-02-25'::date,
  '/journal/une-ambiance-intergenerationnelle/couverture.jpg',
  'Piste de danse sous des jets de fumée rouge',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Créer une ambiance intergénérationnelle est aujourd’hui l’un des plus grands défis de l’événementiel. "},{"type":"text","text":"Mariages","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":", "},{"type":"text","text":"événements privés ou corporate","marks":[{"type":"link","attrs":{"href":"/evenementiel"}}]},{"type":"text","text":" : le public n’a jamais été aussi varié. Adolescents, trentenaires, parents, grands-parents… Tous partagent le même espace, mais pas forcément les mêmes références musicales. Et pourtant, une piste de danse peut – et doit – devenir un terrain d’entente."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Comprendre avant de mixer"}]},{"type":"paragraph","content":[{"type":"text","text":"Faire danser toutes les générations ne consiste pas à empiler des tubes au hasard. C’est une lecture fine du public, de l’énergie de la salle et du moment ("},{"type":"text","text":"voir article : Comment un DJ lit-il une piste de danse ?","marks":[{"type":"link","attrs":{"href":"/journal/comment-un-dj-lit-il-une-piste-de-danse"}},{"type":"italic"}]},{"type":"text","text":"). Chaque génération a ses codes, ses souvenirs, ses rythmes. Le rôle du "},{"type":"text","text":"DJ","marks":[{"type":"link","attrs":{"href":"/mariages"}}]},{"type":"text","text":" n’est pas de choisir un camp, mais de construire des ponts : entre époques, styles et émotions."}]},{"type":"image","attrs":{"src":"/journal/une-ambiance-intergenerationnelle/1.jpg","width":365,"height":545,"alt":"Vinyle sur une platine"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le secret : la narration musicale"}]},{"type":"paragraph","content":[{"type":"text","text":"Une ambiance intergénérationnelle réussie repose sur une narration fluide. Un classique intemporel peut ouvrir la porte à un titre plus récent. Un hit actuel peut être réarrangé ou mixé avec une référence des années 80 ou 90. Ce jeu d’équilibre évite les ruptures et maintient tout le monde sur la piste, sans frustration ni lassitude."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Le respect du dancefloor"}]},{"type":"paragraph","content":[{"type":"text","text":"Faire plaisir à tous, ce n’est pas tout jouer. C’est savoir quand jouer quoi. Le respect du dancefloor passe par l’observation : qui danse, qui s’essouffle, qui arrive, qui repart ("},{"type":"text","text":"voir article : Comment un DJ lit-il une piste de danse ?","marks":[{"type":"link","attrs":{"href":"/journal/comment-un-dj-lit-il-une-piste-de-danse"}},{"type":"italic"}]},{"type":"text","text":"). Une ambiance intergénérationnelle ne sacrifie jamais une génération pour en satisfaire une autre. Elle évolue, respire, s’adapte."}]},{"type":"image","attrs":{"src":"/journal/une-ambiance-intergenerationnelle/2.jpg","width":2400,"height":1600,"alt":"Mains qui fouillent un bac de vinyles"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"La technique au service de l’émotion"}]},{"type":"paragraph","content":[{"type":"text","text":"Sonorisation maîtrisée, volumes équilibrés, éclairages lisibles","marks":[{"type":"link","attrs":{"href":"/a-propos"}}]},{"type":"text","text":" : la technique joue un rôle clé. Une ambiance trop agressive exclut, une ambiance trop sage endort. L’objectif est de créer un espace confortable pour tous, où chacun se sent légitime de danser, quel que soit son âge."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Créer du souvenir collectif"}]},{"type":"paragraph","content":[{"type":"text","text":"Quand plusieurs générations dansent ensemble, l’événement change de dimension. Parents et enfants partagent un moment commun, des souvenirs se créent, des barrières tombent. C’est là que l’ambiance devient mémorable : quand la musique rassemble au lieu de diviser."}]},{"type":"image","attrs":{"src":"/journal/une-ambiance-intergenerationnelle/3.jpg","width":2048,"height":1365,"alt":"Membre de l''équipe Spice Events de dos à la régie, en plein air"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Conclusion : l’ambiance comme langage universel"}]},{"type":"paragraph","content":[{"type":"text","text":"Une ambiance intergénérationnelle réussie n’est pas un compromis, c’est une exigence. Elle demande de la culture musicale, de l’expérience et une vraie sensibilité humaine. Mais quand elle fonctionne, elle transforme une simple soirée en moment fédérateur. Et c’est précisément là que l’événementiel prend tout son sens."}]}]}'::jsonb
) on conflict do nothing;
